function design(site, analyse) {
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const groups = {
    bottomChord: [],
    topChord: [],
    posts: [],
    diagonals: [],
    bottomPlan: [],
    topPlan: [],
    floorBeams: [],
    roofBeams: []
  };
  const nodes = [];
  const topY = 10.2;
  const topZ = 3.45;

  function add(group, a, b) {
    groups[group].push({ a, b });
  }

  for (let i = 0; i < 10; i++) {
    nodes.push({ id: "UL" + i, x: xs[i], y: topY, z: -topZ, joint: "pin" });
    nodes.push({ id: "UR" + i, x: xs[i], y: topY, z: topZ, joint: "pin" });
    add("floorBeams", "L" + i, "R" + i);
    add("roofBeams", "UL" + i, "UR" + i);
  }

  for (let i = 0; i < 9; i++) {
    add("bottomChord", "L" + i, "L" + (i + 1));
    add("bottomChord", "R" + i, "R" + (i + 1));
    add("topChord", "UL" + i, "UL" + (i + 1));
    add("topChord", "UR" + i, "UR" + (i + 1));

    for (const side of ["L", "R"]) {
      add("posts", "U" + side + i, side + i);
      if (i <= 4) {
        add("diagonals", "U" + side + i, side + (i + 1));
      } else {
        add("diagonals", "U" + side + (i + 1), side + i);
      }
    }

    if (i % 2 === 0) {
      add("bottomPlan", "L" + i, "R" + (i + 1));
      add("topPlan", "UL" + i, "UR" + (i + 1));
    } else {
      add("bottomPlan", "R" + i, "L" + (i + 1));
      add("topPlan", "UR" + i, "UL" + (i + 1));
    }
  }

  for (const side of ["L", "R"]) {
    add("posts", "U" + side + 9, side + 9);
  }

  const sections = [
    "CHS33.7x2.6",
    "CHS48.3x3.2",
    "CHS60.3x4",
    "CHS76.1x4",
    "CHS88.9x5",
    "CHS114.3x5",
    "CHS139.7x6.3",
    "CHS168.3x6.3",
    "CHS193.7x6.3",
    "CHS193.7x8",
    "CHS219.1x8",
    "CHS244.5x8",
    "CHS273x10",
    "CHS323.9x10",
    "CHS355.6x12.5",
    "CHS406.4x12.5",
    "CHS457x16"
  ];
  const materials = ["AL7075", "S690", "SS316"];
  const groupNames = Object.keys(groups);
  const note = "A symmetric pair of deep pinned Pratt trusses is tied by alternating top- and deck-plane diagonals; the analysis loop sizes each member family with margin.";

  function makeDesign(specs) {
    const members = [];
    for (const group of groupNames) {
      for (const link of groups[group]) {
        members.push({ a: link.a, b: link.b, spec: specs[group] });
      }
    }
    return {
      note,
      nodes: nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      members
    };
  }

  const cache = new Map();
  let calls = 0;

  function evaluate(specs) {
    const key = groupNames.map(g => specs[g]).join("|");
    if (cache.has(key)) return cache.get(key);

    const d = makeDesign(specs);
    if (calls >= 380) return { design: d, report: null };

    let report;
    try {
      report = analyse(d);
    } catch (e) {
      report = { error: String(e) };
    }
    calls++;
    const result = { design: d, report };
    cache.set(key, result);
    return result;
  }

  function isNumber(v) {
    return typeof v === "number" && isFinite(v);
  }

  function fatigueRatio(report) {
    const f = report && report.fatigueWorst;
    if (isNumber(f)) return f >= 0 && f <= 2 ? f : null;
    if (f && typeof f === "object") {
      for (const k of ["util", "ratio", "maxUtil", "utilization"]) {
        if (isNumber(f[k])) return f[k];
      }
      const range = isNumber(f.range) ? f.range : f.stressRange;
      const limit = isNumber(f.limit) ? f.limit : f.allowable;
      if (isNumber(range) && isNumber(limit) && limit > 0) return range / limit;
    }
    return null;
  }

  function safe(report) {
    if (!report || report.error || report.ok !== true) return false;

    const rb = report.robustness;
    if (rb === false) return false;
    if (rb && typeof rb === "object" &&
        (rb.ok === false || rb.pass === false || rb.passed === false)) return false;

    let maxUtil = report.maxUtil;
    if (!isNumber(maxUtil) && Array.isArray(report.members)) {
      maxUtil = 0;
      for (const m of report.members) {
        if (isNumber(m.util)) maxUtil = Math.max(maxUtil, m.util);
      }
    }
    if (isNumber(maxUtil) && maxUtil > 0.72) return false;

    const fatigue = fatigueRatio(report);
    if (isNumber(fatigue) && fatigue > 0.68) return false;

    let alpha = Infinity;
    if (isNumber(report.alphaCrMin)) alpha = Math.min(alpha, report.alphaCrMin);
    if (isNumber(report.alphaCr)) alpha = Math.min(alpha, report.alphaCr);
    if (alpha < 4.2) return false;

    if (isNumber(report.sag) && isNumber(report.sagLimit) && report.sagLimit > 0 &&
        Math.abs(report.sag) / report.sagLimit > 0.82) return false;
    if (isNumber(report.sway) && isNumber(report.swayLimit) && report.swayLimit > 0 &&
        Math.abs(report.sway) / report.swayLimit > 0.82) return false;

    if (isNumber(report.frequency)) {
      const fMin = isNumber(report.fMin) ? report.fMin : 1.7;
      if (report.frequency < Math.max(2.0, fMin + 0.2)) return false;
    }
    return true;
  }

  function massOf(result) {
    return result && result.report && isNumber(result.report.mass)
      ? result.report.mass
      : Infinity;
  }

  function minimumFor(group, material, current) {
    let lo = 0;
    let hi = sections.length - 1;

    const largest = Object.assign({}, current);
    largest[group] = material + " " + sections[hi];
    if (!safe(evaluate(largest).report)) return null;

    while (lo < hi && calls < 380) {
      const mid = Math.floor((lo + hi) / 2);
      const trial = Object.assign({}, current);
      trial[group] = material + " " + sections[mid];
      if (safe(evaluate(trial).report)) hi = mid;
      else lo = mid + 1;
    }

    const trial = Object.assign({}, current);
    trial[group] = material + " " + sections[lo];
    const result = evaluate(trial);
    return safe(result.report) ? { specs: trial, result } : null;
  }

  let current = {};
  for (const group of groupNames) current[group] = "AL7075 CHS457x16";
  let currentResult = evaluate(current);

  if (!safe(currentResult.report)) {
    for (const material of ["S690", "SS316"]) {
      const trial = {};
      for (const group of groupNames) trial[group] = material + " CHS457x16";
      const result = evaluate(trial);
      if (safe(result.report) && massOf(result) < massOf(currentResult)) {
        current = trial;
        currentResult = result;
      }
    }
  }

  if (safe(currentResult.report)) {
    for (let pass = 0; pass < 2; pass++) {
      let changed = false;

      for (const group of groupNames) {
        let bestSpecs = current;
        let bestResult = currentResult;

        for (const material of materials) {
          const candidate = minimumFor(group, material, current);
          if (candidate && massOf(candidate.result) < massOf(bestResult) - 1e-6) {
            bestSpecs = candidate.specs;
            bestResult = candidate.result;
          }
        }

        if (bestSpecs[group] !== current[group]) {
          current = bestSpecs;
          currentResult = bestResult;
          changed = true;
        }
      }

      if (!changed || calls >= 380) break;
    }
  }

  return makeDesign(current);
}

function design(site, analyse) {
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const midY = 4.7;
  const topY = 10.2;
  const sideZ = 3.45;

  const nodes = [];
  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: "ML" + i, x: xs[i], y: midY, z: -sideZ, joint: "pin" });
    nodes.push({ id: "MR" + i, x: xs[i], y: midY, z: sideZ, joint: "pin" });
    nodes.push({ id: "TL" + i, x: xs[i], y: topY, z: -sideZ, joint: "pin" });
    nodes.push({ id: "TR" + i, x: xs[i], y: topY, z: sideZ, joint: "pin" });
  }

  const groupNames = [
    "bottomChord", "middleChord", "topChord",
    "lowerPost", "upperPost", "lowerDiag", "upperDiag",
    "floorBeam", "midBeam", "roofBeam", "crossBrace",
    "bottomPlan", "midPlan", "topPlan"
  ];
  const groups = {};
  for (const name of groupNames) groups[name] = [];

  function add(group, a, b) {
    groups[group].push({ a, b });
  }

  const sides = [
    { base: "L", mid: "ML", top: "TL" },
    { base: "R", mid: "MR", top: "TR" }
  ];

  for (let i = 0; i < xs.length; i++) {
    add("floorBeam", "L" + i, "R" + i);
    add("midBeam", "ML" + i, "MR" + i);
    add("roofBeam", "TL" + i, "TR" + i);

    add("crossBrace", "ML" + i, "TR" + i);
    add("crossBrace", "MR" + i, "TL" + i);

    for (const side of sides) {
      add("lowerPost", side.base + i, side.mid + i);
      add("upperPost", side.mid + i, side.top + i);
    }
  }

  for (let i = 0; i < xs.length - 1; i++) {
    for (const side of sides) {
      add("bottomChord", side.base + i, side.base + (i + 1));
      add("middleChord", side.mid + i, side.mid + (i + 1));
      add("topChord", side.top + i, side.top + (i + 1));

      if (i < 5) {
        add("lowerDiag", side.mid + i, side.base + (i + 1));
        add("upperDiag", side.top + i, side.mid + (i + 1));
      } else {
        add("lowerDiag", side.mid + (i + 1), side.base + i);
        add("upperDiag", side.top + (i + 1), side.mid + i);
      }
    }

    if (i % 2 === 0) {
      add("bottomPlan", "L" + i, "R" + (i + 1));
      add("midPlan", "ML" + i, "MR" + (i + 1));
      add("topPlan", "TL" + i, "TR" + (i + 1));
    } else {
      add("bottomPlan", "R" + i, "L" + (i + 1));
      add("midPlan", "MR" + i, "ML" + (i + 1));
      add("topPlan", "TR" + i, "TL" + (i + 1));
    }
  }

  const note =
    "I replaced the unbraced rectangular cross-sections with triangulated cross-frames and three-level side and plan trusses, then size the pinned steel tubes with margin.";

  const sections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
    "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4",
    "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5",
    "CHS139.7x5", "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5",
    "CHS406.4x12.5", "CHS457x16"
  ];

  function isNumber(v) {
    return typeof v === "number" && Number.isFinite(v);
  }

  function fatigueRatio(report) {
    const f = report && report.fatigueWorst;
    if (isNumber(f)) return f;
    if (f && typeof f === "object") {
      for (const key of ["util", "ratio", "maxUtil", "utilization"]) {
        if (isNumber(f[key])) return f[key];
      }
      const range = isNumber(f.range) ? f.range : f.stressRange;
      const limit = isNumber(f.limit) ? f.limit : f.allowable;
      if (isNumber(range) && isNumber(limit) && limit > 0) return range / limit;
    }
    return null;
  }

  function safe(report) {
    if (!report || report.error || report.ok !== true) return false;

    const robustness = report.robustness;
    if (robustness === false) return false;
    if (robustness && typeof robustness === "object" &&
        (robustness.ok === false ||
         robustness.pass === false ||
         robustness.passed === false)) return false;

    let maxUtil = isNumber(report.maxUtil) ? report.maxUtil : null;
    if (maxUtil === null && Array.isArray(report.members)) {
      maxUtil = 0;
      for (const member of report.members) {
        if (isNumber(member.util)) maxUtil = Math.max(maxUtil, member.util);
      }
    }
    if (maxUtil !== null && maxUtil > 0.68) return false;

    const fatigue = fatigueRatio(report);
    if (fatigue !== null && fatigue > 0.76) return false;

    let alpha = Infinity;
    if (isNumber(report.alphaCrMin)) alpha = Math.min(alpha, report.alphaCrMin);
    if (isNumber(report.alphaCr)) alpha = Math.min(alpha, report.alphaCr);
    if (alpha < 4.2) return false;

    if (isNumber(report.sag) && isNumber(report.sagLimit) && report.sagLimit > 0 &&
        Math.abs(report.sag) / report.sagLimit > 0.75) return false;
    if (isNumber(report.sway) && isNumber(report.swayLimit) && report.swayLimit > 0 &&
        Math.abs(report.sway) / report.swayLimit > 0.75) return false;

    if (isNumber(report.frequency)) {
      const fMin = isNumber(report.fMin) ? report.fMin : 1.7;
      if (report.frequency < Math.max(1.9, fMin + 0.15)) return false;
    }
    return true;
  }

  function build(choice) {
    const members = [];
    for (const group of groupNames) {
      const spec = "S460 " + sections[choice[group]];
      for (const link of groups[group]) {
        members.push({ a: link.a, b: link.b, spec: spec });
      }
    }
    return {
      note: note,
      nodes: nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      members: members
    };
  }

  const maxCalls = 240;
  let calls = 0;
  const cache = new Map();

  function evaluate(choice) {
    const key = groupNames.map(g => choice[g]).join(",");
    if (cache.has(key)) return cache.get(key);

    const designObject = build(choice);
    if (calls >= maxCalls) return { design: designObject, report: null };

    let report;
    try {
      report = analyse(designObject);
    } catch (e) {
      report = { error: String(e) };
    }
    calls++;

    const result = { design: designObject, report: report };
    cache.set(key, result);
    return result;
  }

  function massOf(result) {
    return result && result.report && isNumber(result.report.mass)
      ? result.report.mass
      : Infinity;
  }

  function minimizeGroup(group, choice) {
    let low = 0;
    let high = choice[group];

    while (low < high && calls < maxCalls - 2) {
      const mid = Math.floor((low + high) / 2);
      const trial = Object.assign({}, choice);
      trial[group] = mid;

      if (safe(evaluate(trial).report)) high = mid;
      else low = mid + 1;
    }

    if (low < high || calls >= maxCalls - 2) return null;

    const trial = Object.assign({}, choice);
    trial[group] = low;
    const result = evaluate(trial);
    return safe(result.report) ? { choice: trial, result: result } : null;
  }

  let current = {};
  for (const group of groupNames) current[group] = sections.length - 1;
  let currentResult = evaluate(current);

  if (safe(currentResult.report)) {
    for (let pass = 0; pass < 2 && calls < maxCalls - 4; pass++) {
      for (const group of groupNames) {
        if (calls >= maxCalls - 4) break;
        if (current[group] === 0) continue;

        const candidate = minimizeGroup(group, current);
        if (candidate &&
            massOf(candidate.result) < massOf(currentResult) - 1e-6) {
          current = candidate.choice;
          currentResult = candidate.result;
        }
      }
    }
  }

  return build(current);
}

function design(site, analyse) {
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const lowerY = -3.95;
  const lowerZ = 3.4;
  const nodes = [];
  const groups = [
    "topChord", "bottomChord", "posts", "sideDiag",
    "deckCross", "bottomCross", "sectionDiag", "deckPlan", "bottomPlan"
  ];
  const links = {};
  for (const g of groups) links[g] = [];

  function add(group, a, b) {
    links[group].push({ a, b });
  }

  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: "BL" + i, x: xs[i], y: lowerY, z: -lowerZ, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xs[i], y: lowerY, z: lowerZ, joint: "pin" });

    add("posts", "L" + i, "BL" + i);
    add("posts", "R" + i, "BR" + i);
    add("deckCross", "L" + i, "R" + i);
    add("bottomCross", "BL" + i, "BR" + i);

    // One compression-capable diagonal triangulates each transverse frame.
    if (i % 2 === 0) add("sectionDiag", "L" + i, "BR" + i);
    else add("sectionDiag", "R" + i, "BL" + i);
  }

  for (let i = 0; i < xs.length - 1; i++) {
    add("topChord", "L" + i, "L" + (i + 1));
    add("topChord", "R" + i, "R" + (i + 1));
    add("bottomChord", "BL" + i, "BL" + (i + 1));
    add("bottomChord", "BR" + i, "BR" + (i + 1));

    for (const side of [
      { deck: "L", lower: "BL" },
      { deck: "R", lower: "BR" }
    ]) {
      if (i < 4) {
        add("sideDiag", side.deck + i, side.lower + (i + 1));
      } else if (i > 4) {
        add("sideDiag", side.deck + (i + 1), side.lower + i);
      } else {
        // X-brace the middle panel for load reversal and torsion.
        add("sideDiag", side.deck + i, side.lower + (i + 1));
        add("sideDiag", side.deck + (i + 1), side.lower + i);
      }
    }

    // Triangulate both horizontal planes.
    if (i % 2 === 0) {
      add("deckPlan", "L" + i, "R" + (i + 1));
      add("bottomPlan", "BL" + i, "BR" + (i + 1));
    } else {
      add("deckPlan", "R" + i, "L" + (i + 1));
      add("bottomPlan", "BR" + i, "BL" + (i + 1));
    }
  }

  const sections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
    "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4",
    "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5",
    "CHS139.7x5", "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5",
    "CHS406.4x12.5", "CHS457x16"
  ];

  const note =
    "I replaced the overhead mechanism with a triangulated underslung twin-side truss, deck and soffit plan bracing, and triangulated transverse frames below the deck; all joints are pinned.";

  function build(choice) {
    const members = [];
    for (const g of groups) {
      const spec = choice[g].material + " " + sections[choice[g].index];
      for (const link of links[g]) {
        members.push({ a: link.a, b: link.b, spec: spec });
      }
    }
    return {
      note: note,
      nodes: nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      members: members
    };
  }

  function isNumber(v) {
    return typeof v === "number" && Number.isFinite(v);
  }

  function fatigueRatio(report) {
    const f = report && report.fatigueWorst;
    if (isNumber(f)) return f >= 0 && f <= 2 ? f : null;
    if (f && typeof f === "object") {
      for (const k of ["util", "ratio", "maxUtil", "utilization"]) {
        if (isNumber(f[k])) return f[k];
      }
      const range = isNumber(f.range) ? f.range : f.stressRange;
      const limit = isNumber(f.limit) ? f.limit : f.allowable;
      if (isNumber(range) && isNumber(limit) && limit > 0) return range / limit;
    }
    return null;
  }

  function safe(report) {
    if (!report || report.error || report.ok !== true) return false;

    const rb = report.robustness;
    if (rb === false) return false;
    if (rb && typeof rb === "object" &&
        (rb.ok === false || rb.pass === false || rb.passed === false)) return false;

    let maxUtil = isNumber(report.maxUtil) ? report.maxUtil : null;
    if (maxUtil === null && Array.isArray(report.members)) {
      maxUtil = 0;
      for (const m of report.members) {
        if (isNumber(m.util)) maxUtil = Math.max(maxUtil, m.util);
      }
    }
    if (maxUtil !== null && maxUtil > 0.58) return false;

    const fatigue = fatigueRatio(report);
    if (fatigue !== null && fatigue > 0.72) return false;

    let alpha = Infinity;
    if (isNumber(report.alphaCrMin)) alpha = Math.min(alpha, report.alphaCrMin);
    if (isNumber(report.alphaCr)) alpha = Math.min(alpha, report.alphaCr);
    if (alpha < 4.5) return false;

    if (isNumber(report.sag) && isNumber(report.sagLimit) && report.sagLimit > 0 &&
        Math.abs(report.sag) / report.sagLimit > 0.76) return false;
    if (isNumber(report.sway) && isNumber(report.swayLimit) && report.swayLimit > 0 &&
        Math.abs(report.sway) / report.swayLimit > 0.76) return false;

    if (isNumber(report.frequency)) {
      const fMin = isNumber(report.fMin) ? report.fMin : 1.7;
      if (report.frequency < Math.max(2.0, fMin + 0.2)) return false;
    }
    return true;
  }

  function cloneChoice(choice) {
    const copy = {};
    for (const g of groups) copy[g] = {
      material: choice[g].material,
      index: choice[g].index
    };
    return copy;
  }

  function keyOf(choice) {
    return groups.map(g => choice[g].material + ":" + choice[g].index).join("|");
  }

  const cache = new Map();
  const maxCalls = 180;
  let calls = 0;

  function evaluate(choice) {
    const key = keyOf(choice);
    if (cache.has(key)) return cache.get(key);

    const d = build(choice);
    if (calls >= maxCalls) return { design: d, report: null };

    let report;
    try {
      report = analyse(d);
    } catch (e) {
      report = { error: String(e) };
    }
    calls++;
    const result = { design: d, report: report };
    cache.set(key, result);
    return result;
  }

  function massOf(result) {
    return result && result.report && isNumber(result.report.mass)
      ? result.report.mass
      : Infinity;
  }

  function minimizeGroup(group, current) {
    let low = 0;
    let high = current[group].index;

    while (low < high && calls < maxCalls - 1) {
      const mid = Math.floor((low + high) / 2);
      const trial = cloneChoice(current);
