        add("web" + zone, side.deck + (i + 1), side.lower + i);
      } else {
        add("web" + zone, side.deck + i, side.lower + (i + 1));
        add("web" + zone, side.deck + (i + 1), side.lower + i);
      }
    }

    if (i % 2 === 0) {
      add("deckPlan", "L" + i, "R" + (i + 1));
      add("bottomPlan", "BL" + i, "BR" + (i + 1));
    } else {
      add("deckPlan", "R" + i, "L" + (i + 1));
      add("bottomPlan", "BR" + i, "BL" + (i + 1));
    }
  }

  function cloneChoice(choice) {
    const copy = {};
    for (const g of groupNames) {
      copy[g] = { material: choice[g].material, index: choice[g].index };
    }
    return copy;
  }

  function build(choice) {
    const members = [];
    for (const g of groupNames) {
      const spec = choice[g].material + " " + sections[choice[g].index];
      for (const link of links[g]) {
        members.push({ a: link.a, b: link.b, spec: spec });
      }
    }

    return {
      note,
      nodes: nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      joints: {},
      members
    };
  }

  function isNumber(v) {
    return typeof v === "number" && Number.isFinite(v);
  }

  function nominalPass(report) {
    if (!report || report.error) return false;
    if (report.ok === false || report.ok === 0) return false;

    if (isNumber(report.score)) return report.score > 0;
    return report.ok === true;
  }

  function fatigueUtil(report) {
    const f = report && report.fatigueWorst;
    if (isNumber(f)) return f;

    if (f && typeof f === "object") {
      for (const k of ["util", "ratio", "maxUtil", "utilization"]) {
        if (isNumber(f[k])) return f[k];
      }
      const range = isNumber(f.range) ? f.range : f.stressRange;
      const limit = isNumber(f.limit) ? f.limit : f.allowable;
      if (isNumber(range) && isNumber(limit) && limit > 0) return range / limit;
    }
    return null;
  }

  function marginPass(report) {
    if (!nominalPass(report)) return false;

    const rb = report.robustness;
    if (rb === false) return false;
    if (rb && typeof rb === "object") {
      if (rb.ok === false || rb.pass === false || rb.passed === false) return false;
      if (Array.isArray(rb.failures) && rb.failures.length > 0) return false;
    }

    let worstUtil = 0;
    let hasUtil = false;

    if (Array.isArray(report.cases)) {
      for (const c of report.cases) {
        if (c && isNumber(c.maxUtil)) {
          worstUtil = Math.max(worstUtil, c.maxUtil);
          hasUtil = true;
        }
      }
    }
    if (Array.isArray(report.members)) {
      for (const m of report.members) {
        if (m && isNumber(m.util)) {
          worstUtil = Math.max(worstUtil, m.util);
          hasUtil = true;
        }
      }
    }
    if (!hasUtil && isNumber(report.maxUtil)) {
      worstUtil = report.maxUtil;
      hasUtil = true;
    }
    if (hasUtil && worstUtil > 0.58) return false;

    const fatigue = fatigueUtil(report);
    if (fatigue !== null && fatigue > 0.64) return false;

    let alpha = Infinity;
    if (isNumber(report.alphaCrMin)) alpha = Math.min(alpha, report.alphaCrMin);
    if (isNumber(report.alphaCr)) alpha = Math.min(alpha, report.alphaCr);
    if (alpha < 10) return false;

    if (isNumber(report.sag) && isNumber(report.sagLimit) && report.sagLimit > 0 &&
        Math.abs(report.sag) / report.sagLimit > 0.82) return false;
    if (isNumber(report.sway) && isNumber(report.swayLimit) && report.swayLimit > 0 &&
        Math.abs(report.sway) / report.swayLimit > 0.82) return false;

    if (isNumber(report.frequency)) {
      const fMin = isNumber(report.fMin) ? report.fMin : 1.7;
      if (report.frequency < Math.max(1.95, fMin + 0.15)) return false;
    }

    return true;
  }

  const MAX_CALLS = 398;
  let calls = 0;
  const cache = new Map();

  function keyOf(choice) {
    return groupNames.map(g =>
      g + ":" + choice[g].material + ":" + choice[g].index
    ).join("|");
  }

  function evaluate(choice) {
    const key = keyOf(choice);
    if (cache.has(key)) return cache.get(key);

    const d = build(choice);
    if (calls >= MAX_CALLS) return { design: d, report: null };

    let report;
    try {
      report = analyse(d);
    } catch (e) {
      report = { error: String(e) };
    }
    calls++;

    const result = { design: d, report };
    cache.set(key, result);
    return result;
  }

  function massOf(result) {
    return result && result.report && isNumber(result.report.mass)
      ? result.report.mass
      : Infinity;
  }

  let current = {};
  for (const g of groupNames) {
    current[g] = { material: "S460", index: sections.length - 1 };
  }
  let currentResult = evaluate(current);

  function adoptIfLighter(trial, result) {
    if (!marginPass(result.report)) return false;

    if (massOf(result) < massOf(currentResult) - 1e-6) {
      current = trial;
      currentResult = result;
      return true;
    }
    return false;
  }

  function shrinkGroup(group) {
    if (!marginPass(currentResult.report)) return false;

    const start = current[group].index;
    if (start <= 0 || calls >= MAX_CALLS - 1) return false;

    let low = 0;
    let high = start;

    while (low < high && calls < MAX_CALLS - 1) {
      const mid = Math.floor((low + high) / 2);
      const trial = cloneChoice(current);
      trial[group].index = mid;

      if (marginPass(evaluate(trial).report)) high = mid;
      else low = mid + 1;
    }

    if (calls >= MAX_CALLS) return false;
    const trial = cloneChoice(current);
    trial[group].index = low;
    return adoptIfLighter(trial, evaluate(trial));
  }

  function tryMaterial(group, material) {
    if (!groupNames.includes(group) ||
        current[group].material === material ||
        calls >= MAX_CALLS - 1) return false;

    let high = current[group].index;
    let upper = cloneChoice(current);
    upper[group] = { material, index: high };
    let upperResult = evaluate(upper);

    if (!marginPass(upperResult.report)) {
      high = sections.length - 1;
      upper = cloneChoice(current);
      upper[group] = { material, index: high };
      upperResult = evaluate(upper);
      if (!marginPass(upperResult.report)) return false;
    }

    let low = 0;
    while (low < high && calls < MAX_CALLS - 1) {
      const mid = Math.floor((low + high) / 2);
      const trial = cloneChoice(current);
      trial[group] = { material, index: mid };

      if (marginPass(evaluate(trial).report)) high = mid;
      else low = mid + 1;
    }

    if (calls >= MAX_CALLS) return false;
    const trial = cloneChoice(current);
    trial[group] = { material, index: low };
    return adoptIfLighter(trial, evaluate(trial));
  }

  const order = [];
  for (let i = 4; i >= 0; i--) {
    for (const prefix of ["top", "bottom", "web", "post"]) {
      const g = prefix + i;
      if (groupNames.includes(g)) order.push(g);
    }
  }
  for (const g of [
    "sectionDiag", "deckCross", "bottomCross", "deckPlan", "bottomPlan"
  ]) {
    if (groupNames.includes(g)) order.push(g);
  }

  function sweep(limit) {
    for (const g of order) {
      if (calls + 6 > limit) break;
      shrinkGroup(g);
    }
  }

  if (marginPass(currentResult.report)) {
    sweep(165);

    const alternatives = [
      ["deckPlan", "AL7075"],
      ["bottomPlan", "AL7075"],
      ["sectionDiag", "AL7075"],
      ["deckCross", "AL7075"],
      ["bottomCross", "AL7075"],
      ["web4", "AL7075"],
      ["web3", "AL7075"],
      ["web2", "AL7075"],
      ["web1", "AL7075"],
      ["web0", "AL7075"],
      ["top4", "S690"],
      ["bottom4", "S690"]
    ];

    for (const [group, material] of alternatives) {
      if (calls + 8 > 260) break;
      tryMaterial(group, material);
    }

    sweep(MAX_CALLS - 1);
  }

  return build(current);
}

