    vertIn: ['S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS139.7x5','S460 CHS168.3x6.3','S460 CHS193.7x6.3','S460 CHS219.1x8','S460 CHS244.5x8'],
    diagEnd: ['S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS114.3x5','S460 CHS139.7x5','S460 CHS168.3x6.3','S460 CHS193.7x6.3','S460 CHS219.1x8','S460 CHS244.5x8'],
    diagMid: ['S460 CHS42.4x3.2','S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS114.3x5','S460 CHS139.7x5','S460 CHS168.3x6.3','S460 CHS193.7x6.3','S460 CHS219.1x8'],
    crossBot: ['S460 CHS48.3x3.2','S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS139.7x5','S460 CHS168.3x6.3','S460 CHS193.7x8'],
    crossTop: ['S460 CHS42.4x3.2','S460 CHS48.3x3.2','S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS139.7x5','S460 CHS168.3x6.3'],
    hDiagBot: ['S460 CHS33.7x2.6','S460 CHS42.4x3.2','S460 CHS48.3x3.2','S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS139.7x5'],
    hDiagTop: ['S460 CHS33.7x2.6','S460 CHS42.4x3.2','S460 CHS48.3x3.2','S460 CHS60.3x3.2','S460 CHS76.1x3.2','S460 CHS88.9x4','S460 CHS114.3x4','S460 CHS139.7x5']
  };

  const hugeAssign = {
    topEnd: 'S460 CHS244.5x8',
    topMid: 'S460 CHS457x16',
    botEnd: 'S460 CHS244.5x8',
    botMid: 'S460 CHS457x16',
    vertEnd: 'S460 CHS273x10',
    vertIn: 'S460 CHS219.1x8',
    diagEnd: 'S460 CHS273x10',
    diagMid: 'S460 CHS219.1x8',
    crossBot: 'S460 CHS193.7x8',
    crossTop: 'S460 CHS193.7x8',
    hDiagBot: 'S460 CHS168.3x6.3',
    hDiagTop: 'S460 CHS168.3x6.3'
  };

  function build(assign) {
    const nodes = [];
    for (let i = 0; i < 10; i++) {
      nodes.push({id: 'TL' + i, x: xs[i], y: H, z: -2.9});
      nodes.push({id: 'TR' + i, x: xs[i], y: H, z: 2.9});
    }
    const members = [];
    const add = (a, b, s) => members.push([a, b, s]);
    const gTop = i => (i <= 1 || i >= 7) ? 'topEnd' : 'topMid';
    const gBot = i => (i <= 1 || i >= 7) ? 'botEnd' : 'botMid';
    const gVert = i => (i === 0 || i === 9) ? 'vertEnd' : 'vertIn';
    const gDiag = i => (i <= 1 || i >= 7) ? 'diagEnd' : 'diagMid';

    for (let i = 0; i < 9; i++) {
      add('TL' + i, 'TL' + (i + 1), assign[gTop(i)]);
      add('TR' + i, 'TR' + (i + 1), assign[gTop(i)]);
      add('L' + i, 'L' + (i + 1), assign[gBot(i)]);
      add('R' + i, 'R' + (i + 1), assign[gBot(i)]);
    }
    for (let i = 0; i < 10; i++) {
      add('L' + i, 'TL' + i, assign[gVert(i)]);
      add('R' + i, 'TR' + i, assign[gVert(i)]);
      add('L' + i, 'R' + i, assign.crossBot);
      add('TL' + i, 'TR' + i, assign.crossTop);
    }
    for (let i = 0; i < 9; i++) {
      add('TL' + i, 'L' + (i + 1), assign[gDiag(i)]);
      add('TR' + i, 'R' + (i + 1), assign[gDiag(i)]);
      if (i % 2 === 0) {
        add('L' + i, 'R' + (i + 1), assign.hDiagBot);
        add('TL' + i, 'TR' + (i + 1), assign.hDiagTop);
      } else {
        add('R' + i, 'L' + (i + 1), assign.hDiagBot);
        add('TR' + i, 'TL' + (i + 1), assign.hDiagTop);
      }
    }
    return {note: 'Parallel-chord through truss, S460 CHS, pinned joints', nodes, members};
  }

  const cache = new Map();
  const evals = [];
  let calls = 0;

  function getEntry(assign) {
    const key = groups.map(g => assign[g]).join('|');
    if (cache.has(key)) return cache.get(key);
    if (calls >= 380) return null;
    let r = null;
    try {
      const d = build(assign);
      r = analyse(d);
    } catch (e) {
      r = {error: String(e), ok: false, mass: 1e12};
    }
    calls++;
    const entry = {assign: Object.assign({}, assign), r: r};
    cache.set(key, entry);
    evals.push(entry);
    return entry;
  }

  function strict(r) {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.84) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 4.0) return false;
    if (typeof r.frequency === 'number' && r.frequency < 1.85) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.8 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.8 * r.swayLimit) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.85) return false;
    if (r.robustness === false) return false;
    return true;
  }

  function relaxed(r) {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.95) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.2) return false;
    if (typeof r.frequency === 'number' && r.frequency < 1.75) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.95) return false;
    if (r.robustness === false) return false;
    return true;
  }

  function score(r) {
    if (!r || r.error) return 1e12;
    let s = (typeof r.mass === 'number' ? r.mass : 1e9);
    if (!r.ok) return s + 1e9;
    if (typeof r.maxUtil === 'number') s += Math.max(0, r.maxUtil - 0.85) * 50000;
    if (typeof r.alphaCr === 'number') s += Math.max(0, 4.0 - r.alphaCr) * 5000;
    if (typeof r.frequency === 'number') s += Math.max(0, 1.85 - r.frequency) * 5000;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number') s += Math.max(0, r.sag / r.sagLimit - 0.8) * 50000;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number') s += Math.max(0, r.sway / r.swayLimit - 0.8) * 50000;
    if (typeof r.fatigueWorst === 'number') s += Math.max(0, r.fatigueWorst - 0.85) * 50000;
    if (r.robustness === false) s += 1e6;
    return s;
  }

  let currentAssign = Object.assign({}, hugeAssign);
  let currentEntry = getEntry(currentAssign);
  if (!currentEntry) {
    currentEntry = {assign: currentAssign, r: {ok: false, mass: 1e12}};
  }

  const order = ['topMid','topEnd','botMid','botEnd','vertEnd','vertIn','diagEnd','diagMid','crossBot','crossTop','hDiagBot','hDiagTop'];
  let improved = true;
  let passes = 0;
  while (improved && passes < 4 && calls < 375) {
    improved = false;
    for (const g of order) {
      if (calls >= 378) break;
      let bestSpec = currentAssign[g];
      let bestEntry = currentEntry;
      let bestScore = score(currentEntry.r);
      for (const spec of specs[g]) {
        if (spec === currentAssign[g]) continue;
        const trial = Object.assign({}, currentAssign);
        trial[g] = spec;
        const entry = getEntry(trial);
        if (!entry) continue;
        const sc = score(entry.r);
        if (sc < bestScore - 1e-6) {
          bestScore = sc;
          bestSpec = spec;
          bestEntry = entry;
        }
      }
      if (bestSpec !== currentAssign[g]) {
        currentAssign = Object.assign({}, currentAssign);
        currentAssign[g] = bestSpec;
        currentEntry = bestEntry;
        improved = true;
      }
    }
    passes++;
  }

  let bestStrict = null, bestRelaxed = null, bestOk = null, bestAny = null;
  for (const e of evals) {
    const r = e.r;
    if (!r || r.error) continue;
    if (strict(r)) {
      if (!bestStrict || (typeof r.mass === 'number' && r.mass < bestStrict.r.mass)) bestStrict = e;
    } else if (relaxed(r)) {
      if (!bestRelaxed || (typeof r.mass === 'number' && r.mass < bestRelaxed.r.mass)) bestRelaxed = e;
    } else if (r.ok) {
      if (!bestOk || (typeof r.mass === 'number' && r.mass < bestOk.r.mass)) bestOk = e;
    } else {
      if (!bestAny || (typeof r.mass === 'number' && r.mass < (bestAny.r.mass || 1e12))) bestAny = e;
    }
  }

  const chosen = bestStrict || bestRelaxed || bestOk || bestAny || currentEntry;
  const out = build(chosen.assign);
  const m = chosen.r && typeof chosen.r.mass === 'number' ? Math.round(chosen.r.mass) : '?';
  out.note = 'Parallel-chord through truss, S460 CHS, pin joints; mass ' + m + ' kg';
  return out;
}

