    'S460 CHS244.5x8'
  ];

  const specs = {
    topEnd: chordSpecs,
    topMid: chordSpecs,
    botEnd: chordSpecs,
    botMid: chordSpecs,
    vertEnd: vertSpecs,
    vertMid: vertSpecs,
    diagEnd: diagSpecs,
    diagMid: diagSpecs,
    topTrans: braceSpecs,
    topBrace: braceSpecs,
    bottomTrans: braceSpecs,
    bottomBrace: braceSpecs,
    crossDiag: crossSpecs
  };

  function groupTop(i) { return (i <= 1 || i >= 7) ? 'topEnd' : 'topMid'; }
  function groupBot(i) { return (i <= 1 || i >= 7) ? 'botEnd' : 'botMid'; }
  function groupVert(i) { return (i <= 1 || i >= 8) ? 'vertEnd' : 'vertMid'; }
  function groupDiag(i) { return (i <= 1 || i >= 7) ? 'diagEnd' : 'diagMid'; }

  function build(assign) {
    const nodes = [];
    const members = [];
    const add = (a, b, g) => members.push([a, b, assign[g]]);

    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'TL' + i, x: xs[i], y: H[i], z: -2.9 });
      nodes.push({ id: 'TR' + i, x: xs[i], y: H[i], z: 2.9 });
    }
    for (const i of S) {
      nodes.push({ id: 'ML' + i, x: xs[i], y: ym, z: -2.9 });
      nodes.push({ id: 'MR' + i, x: xs[i], y: ym, z: 2.9 });
    }

    // Longitudinal top chord.
    for (let i = 0; i < 9; i++) {
      add('TL' + i, 'TL' + (i + 1), groupTop(i));
      add('TR' + i, 'TR' + (i + 1), groupTop(i));
    }

    // Longitudinal deck chord.
    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1), groupBot(i));
      add('R' + i, 'R' + (i + 1), groupBot(i));
    }

    // Top transverse beams.
    for (let i = 0; i < 10; i++) {
      add('TL' + i, 'TR' + i, 'topTrans');
    }

    // Bottom transverse beams.
    for (let i = 0; i < 10; i++) {
      add('L' + i, 'R' + i, 'bottomTrans');
    }

    // Top lateral bracing.
    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) {
        add('TL' + i, 'TR' + (i + 1), 'topBrace');
      } else {
        add('TR' + i, 'TL' + (i + 1), 'topBrace');
      }
    }

    // Bottom lateral bracing.
    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) {
        add('L' + i, 'R' + (i + 1), 'bottomBrace');
      } else {
        add('R' + i, 'L' + (i + 1), 'bottomBrace');
      }
    }

    // Side verticals, split at mid-height where transverse cross frames occur.
    for (let i = 0; i < 10; i++) {
      const gv = groupVert(i);
      if (S.indexOf(i) >= 0) {
        add('L' + i, 'ML' + i, gv);
        add('ML' + i, 'TL' + i, gv);
        add('R' + i, 'MR' + i, gv);
        add('MR' + i, 'TR' + i, gv);
      } else {
        add('L' + i, 'TL' + i, gv);
        add('R' + i, 'TR' + i, gv);
      }
    }

    // Side web diagonals, one per panel per side.
    for (let i = 0; i < 9; i++) {
      const gd = groupDiag(i);
      if (i % 2 === 0) {
        add('TL' + i, 'L' + (i + 1), gd);
        add('TR' + i, 'R' + (i + 1), gd);
      } else {
        add('L' + i, 'TL' + (i + 1), gd);
        add('R' + i, 'TR' + (i + 1), gd);
      }
    }

