    // mid node, preventing a local x-direction mechanism from split verticals.
    for (const i of S) {
      add('ML' + i, 'TR' + i, 'crossDiag');
      if (i + 1 < 10) add('ML' + i, 'TR' + (i + 1), 'crossDiag');
      else add('ML' + i, 'TR' + (i - 1), 'crossDiag');

      add('MR' + i, 'TL' + i, 'crossDiag');
      if (i + 1 < 10) add('MR' + i, 'TL' + (i + 1), 'crossDiag');
      else add('MR' + i, 'TL' + (i - 1), 'crossDiag');
    }

    return {
      note: 'Bowstring-through space truss with upper transverse cross frames; conservative S460 CHS sections.',
      nodes,
      members
    };
  }

  const initialAssign = {
    topEnd: 'S460 CHS355.6x12.5',
    topMid: 'S460 CHS457x16',
    botEnd: 'S460 CHS355.6x12.5',
    botMid: 'S460 CHS457x16',
    vertEnd: 'S460 CHS219.1x8',
    vertMid: 'S460 CHS193.7x8',
    diagEnd: 'S460 CHS244.5x8',
    diagMid: 'S460 CHS219.1x8',
    topTrans: 'S460 CHS139.7x6.3',
    topBrace: 'S460 CHS114.3x5',
    bottomTrans: 'S460 CHS139.7x6.3',
    bottomBrace: 'S460 CHS114.3x5',
    crossDiag: 'S460 CHS168.3x6.3'
  };

  const cache = new Map();
  const evals = [];
  let calls = 0;

  function entryScore(r) {
    if (!r || r.error) return 1e15;
    let s = (typeof r.mass === 'number' ? r.mass : 1e9);
    if (r.ok !== true) s += 1e12;

    const mu = r.maxUtil;
    if (typeof mu === 'number') {
      s += Math.max(0, mu - 0.68) * 1e8;
      s += Math.max(0, mu - 0.85) * 5e8;
    }

    const ac = r.alphaCr;
    if (typeof ac === 'number') {
      s += Math.max(0, 4.5 - ac) * 5e6;
      s += Math.max(0, 3.2 - ac) * 5e7;
    }

    const fr = r.frequency;
    if (typeof fr === 'number') {
      s += Math.max(0, 2.0 - fr) * 5e6;
      s += Math.max(0, 1.75 - fr) * 5e7;
    }

    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sagLimit > 0) {
      const q = r.sag / r.sagLimit;
      s += Math.max(0, q - 0.68) * 5e8;
      s += Math.max(0, q - 0.90) * 1e9;
    }

    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.swayLimit > 0) {
      const q = r.sway / r.swayLimit;
      s += Math.max(0, q - 0.68) * 5e8;
      s += Math.max(0, q - 0.90) * 1e9;
    }

    if (typeof r.fatigueWorst === 'number') {
      s += Math.max(0, r.fatigueWorst - 0.68) * 2e8;
      s += Math.max(0, r.fatigueWorst - 0.90) * 5e8;
    }

    if (r.robustness === false) s += 1e10;
    return s;
  }

  function evalAssign(assign) {
