    if (cache.has(key)) return cache.get(key);
    if (calls >= 390) return null;

    let r;
    try {
      r = analyse(build(assign));
    } catch (e) {
      r = { error: String(e), ok: false, mass: 1e12 };
    }
    calls++;
    const entry = { assign: Object.assign({}, assign), r };
    cache.set(key, entry);
    evals.push(entry);
    return entry;
  }

  let currentAssign = Object.assign({}, initialAssign);
  let currentEntry = evalAssign(currentAssign);

  const order = [
    'botMid', 'topMid', 'botEnd', 'topEnd',
    'diagMid', 'diagEnd', 'vertMid', 'vertEnd',
    'crossDiag', 'topTrans', 'bottomTrans',
    'topBrace', 'bottomBrace'
  ];

  if (currentEntry) {
    let passes = 0;
    while (passes < 3 && calls < 370) {
      let improved = false;

      for (const g of order) {
        if (calls >= 385) break;

        let bestSpec = currentAssign[g];
        let bestEntry = currentEntry;
        let bestScore = entryScore(currentEntry.r);

        for (const spec of specs[g]) {
          if (spec === currentAssign[g]) continue;
          const trial = Object.assign({}, currentAssign);
          trial[g] = spec;
          const entry = evalAssign(trial);
          if (!entry) continue;
          const sc = entryScore(entry.r);
          if (sc < bestScore - 1e-7) {
            bestScore = sc;
            bestSpec = spec;
            bestEntry = entry;
          }
        }

        if (bestSpec !== currentAssign[g]) {
          currentAssign = Object.assign({}, currentAssign);
          currentAssign[g] = bestSpec;
          currentEntry = bestEntry;
          improved = true;
        }
      }

      passes++;
      if (!improved) break;
      if (calls >= 370) break;
    }
  }

  let bestEntry = null;
  let bestScore = 1e100;

  for (const e of evals) {
    const sc = entryScore(e.r);
    if (sc < bestScore) {
      bestScore = sc;
      bestEntry = e;
    }
  }

  if (!bestEntry) bestEntry = currentEntry;
  if (!bestEntry) bestEntry = { assign: initialAssign, r: { mass: 0, ok: false } };

  const out = build(bestEntry.assign);
  const massText = (bestEntry.r && typeof bestEntry.r.mass === 'number')
    ? Math.round(bestEntry.r.mass)
    : '?';

  out.note = 'Bowstring-through space truss with upper transverse cross frames; S460 CHS; mass ' + massText + ' kg';
  return out;
}

