    for (let j = 0; j < XN - 1; j++) {
      for (const side of ['L', 'R']) {
        if (j % 2 === 0) {
          add(deckId(side, j), 'B' + side + (j + 1), 'sideDiagLower');
          add('T' + side + j, deckId(side, j + 1), 'sideDiagUpper');
