        add(deckId('L', j), deckId('R', j + 1), 'horizBraceDeck');
      } else {
        add(deckId('R', j), deckId('L', j + 1), 'horizBraceDeck');
      }

      if (j % 2 === 0) {
        add('TL' + j, 'TR' + (j + 1), 'horizBraceTop');
      } else {
        add('TR' + j, 'TL' + (j + 1), 'horizBraceTop');
      }
    }

    // Transverse vertical bracing in the open under-deck band (-4 m to 0 m).
    for (let j = 0; j < XN; j++) {
      if (j % 2 === 0) {
        add('BL' + j, deckId('R', j), 'lowerCrossBrace');
      } else {
        add('BR' + j, deckId('L', j), 'lowerCrossBrace');
      }
