    try {
      r = analyse(build(assign));
    } catch (e) {
      r = { error: String(e), ok: false, mass: 1e12 };
    }
    calls++;
    const entry = { assign: Object.assign({}, assign), r };
    cache.set(key, entry);
    evals.push(entry);
    return entry;
  }

