  let currentEntry = evaluate(current);

  const maxIdx = {};
  for (const g of groups) maxIdx[g] = cands[g].length - 1;
  const maxAssign = assignFromIndices(maxIdx);
  let maxEntry = null;

  if (!currentEntry || !meets(currentEntry.r, STRICT)) {
