        currentEntry = maxEntry;
      } else if (currentEntry && meets(currentEntry.r, MOD)) {
        // Keep the initial design.
      } else {
        current = Object.assign({}, maxAssign);
        currentEntry = maxEntry;
      }
    }
  }

  const order = groups.slice();

  for (let pass = 0; pass < 3 && calls < MAX_CALLS - 10; pass++) {
    let improved = false;

    for (const g of order) {
      if (calls >= MAX_CALLS - 5) break;

      const list = cands[g];
      let curSpec = current[g];
      let curIdx = list.indexOf(curSpec);
      if (curIdx < 0) curIdx = list.length - 1;

      let chosenSpec = curSpec;
      let chosenEntry = currentEntry;

      // Scan from the smallest section upward and take the first that still
      // satisfies the active robustness target.
      for (let i = 0; i < curIdx; i++) {
        if (calls >= MAX_CALLS - 2) break;

        const trial = Object.assign({}, current);
        trial[g] = list[i];
        const e = evaluate(trial);
        if (!e) continue;

        if (meets(e.r, target)) {
          chosenSpec = list[i];
          chosenEntry = e;
          break;
        }
      }

      if (chosenSpec !== curSpec && chosenEntry) {
        current = Object.assign({}, current);
        current[g] = chosenSpec;
        currentEntry = chosenEntry;
        improved = true;
      }
    }

    if (!improved) break;
  }

  let best = null;
  let bestMass = Infinity;

  for (const e of evals) {
    if (!meets(e.r, target)) continue;
    const m = (e.r && typeof e.r.mass === 'number') ? e.r.mass : 1e12;
    if (m < bestMass) {
      bestMass = m;
      best = e;
    }
  }

  if (!best) {
    if (currentEntry && meets(currentEntry.r, target)) {
      best = currentEntry;
    } else if (maxEntry) {
      best = maxEntry;
    } else {
      best = currentEntry;
    }
  }

  if (!best) {
    return build(assignFromIndices(initIdx));
  }

  const out = build(best.assign);
  const massText = (best.r && typeof best.r.mass === 'number')
    ? Math.round(best.r.mass)
    : '?';

  out.note = 'Three-level through/under-deck space truss with 19 x-stations, three horizontal diaphragms, under-deck transverse bracing, and upper end cross-frames; S460 CHS; mass ' + massText + ' kg';

  return out;
}

