    else target = OKT;
  }

  let current = clone(chosen.assign);
  let currentEntry = chosen;

  function reduceGroup(g) {
    const curSpec = current[g];
    const curIdx = SEC.indexOf(curSpec);
    if (curIdx <= 0) return false;

    let lo = 0;
    let hi = curIdx - 1;
    let bestIdx = curIdx;
    let bestEntry = currentEntry;

    while (lo <= hi && calls < MAX_CALLS - 4) {
      const mid = Math.floor((lo + hi) / 2);
      const trial = clone(current);
      trial[g] = SEC[mid];
      const e = evaluate(trial);
      if (!e) break;

      if (meets(e.r, target)) {
        bestIdx = mid;
        bestEntry = e;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }

    if (bestIdx < curIdx) {
      current = clone(current);
      current[g] = SEC[bestIdx];
      currentEntry = bestEntry;
      return true;
    }
    return false;
  }

  for (let pass = 0; pass < 3 && calls < MAX_CALLS - 10; pass++) {
    let changed = false;
    for (const g of groups) {
      if (calls >= MAX_CALLS - 8) break;
      if (reduceGroup(g)) changed = true;
    }
    if (!changed) break;
  }

  let strictBest = null;
  let relaxBest = null;
  let okBest = null;
  let violBest = null;
  let violMin = Infinity;

  for (const e of evals) {
    if (!e || !e.r) continue;

    if (meets(e.r, STRICT)) {
      if (!strictBest || e.r.mass < strictBest.r.mass) strictBest = e;
    }
    if (meets(e.r, RELAX)) {
      if (!relaxBest || e.r.mass < relaxBest.r.mass) relaxBest = e;
    }
    if (e.r.ok === true) {
      if (!okBest || e.r.mass < okBest.r.mass) okBest = e;
    }

    const vv = violation(e.r);
    if (vv < violMin) {
      violMin = vv;
      violBest = e;
    }
  }

  const finalEntry = strictBest || relaxBest || okBest || violBest || chosen || currentEntry;
  const out = build(finalEntry ? finalEntry.assign : all457);
  const massText = (finalEntry && finalEntry.r && typeof finalEntry.r.mass === 'number')
    ? Math.round(finalEntry.r.mass)
    : '?';

  out.note = 'Three-level through/under-deck space truss, 19 x-stations, full horizontal diaphragms and under-deck bracing; S460 CHS with enlarged deck/fatigue-critical bracing; mass ' + massText + ' kg';
  return out;
}

function design(site, analyse) {
  // ---------------------------------------------------------------------
  // A very light, fully triangulated triangular under-deck space truss.
  // Existing deck edge nodes L0..L9 / R0..R9 are used as the upper
  // (compression) chord.  A single C0..C9 chain at y=-4.30, z=0 is the
  // lower (tension) chord.  The resulting triangular tube is braced on
  // its two sloped sides and on the deck plane.  All members lie below
  // y=0, so the traffic envelope is untouched; the lowest node is above
  // the railway keep-clear box.
  // ---------------------------------------------------------------------

  const CHS = [
    'CHS33.7x2.6','CHS42.4x3.2','CHS48.3x3.2','CHS60.3x3.2','CHS60.3x4',
    'CHS76.1x3.2','CHS76.1x4','CHS88.9x4','CHS88.9x5','CHS114.3x4',
    'CHS114.3x5','CHS139.7x5','CHS168.3x5','CHS139.7x6.3','CHS168.3x6.3',
    'CHS193.7x6.3','CHS193.7x8','CHS219.1x8','CHS244.5x8','CHS273x10',
    'CHS323.9x10','CHS355.6x12.5','CHS406.4x12.5','CHS457x16'
  ];
  const SEC = CHS.map(s => 'S460 ' + s);

  const groups = [
    'topChord',
    'bottomChord',
    'vBrace',
    'sideDiag',
    'deckDiag',
    'deckTrans'
  ];

  const XS = [];
  for (let i = 0; i < 10; i++) XS.push(43.5 * i / 9);

  const YB = -4.30;

  function buildTri(assign) {
    const nodes = [];
    const members = [];

    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'C' + i, x: XS[i], y: YB, z: 0 });
    }

    const add = (a, b, g) => members.push([a, b, assign[g]]);

    // Longitudinal chords.
    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1), 'topChord');
      add('R' + i, 'R' + (i + 1), 'topChord');
      add('C' + i, 'C' + (i + 1), 'bottomChord');
    }

    // Transverse triangles at every station and deck transverse struts.
    for (let i = 0; i < 10; i++) {
      add('L' + i, 'R' + i, 'deckTrans');
      add('L' + i, 'C' + i, 'vBrace');
      add('R' + i, 'C' + i, 'vBrace');
    }

    // Longitudinal bracing of the two sloped triangular faces and of the
    // deck plane.  One diagonal per panel, alternating.
    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) {
        add('L' + i, 'C' + (i + 1), 'sideDiag');
        add('R' + i, 'C' + (i + 1), 'sideDiag');
        add('L' + i, 'R' + (i + 1), 'deckDiag');
      } else {
        add('C' + i, 'L' + (i + 1), 'sideDiag');
        add('C' + i, 'R' + (i + 1), 'sideDiag');
        add('R' + i, 'L' + (i + 1), 'deckDiag');
      }
    }

    return {
      note: 'Triangular under-deck space truss',
      nodes,
      members
    };
  }

  function clone(a) {
    const b = {};
    for (const g of groups) b[g] = a[g];
    return b;
  }

  const cache = new Map();
  const evals = [];
  let calls = 0;
  const MAXCALLS = 380;

  function evaluate(assign) {
    const key = groups.map(g => assign[g]).join('|');
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAXCALLS) return null;

    let r;
    try {
      r = analyse(buildTri(assign));
    } catch (e) {
      r = { error: String(e), ok: false, mass: 1e12 };
    }

    calls++;
    const entry = { assign: clone(assign), r };
    cache.set(key, entry);
    evals.push(entry);
    return entry;
  }

  // Conservative nominal targets.  The first pass is deliberately very
  // strict so the solution has margin against the built-unit scatter.
  const SAFE = {
    util: 0.55,
    fatigue: 0.65,
    alpha: 6.0,
    freq: 2.20,
    sag: 0.55,
    sway: 0.55,
    settle: 0.75,
    ice: 0.75,
    oneSide: 0.68
  };

  const MOD = {
    util: 0.68,
    fatigue: 0.75,
    alpha: 5.0,
    freq: 2.00,
    sag: 0.70,
    sway: 0.70,
    settle: 0.86,
    ice: 0.86,
    oneSide: 0.80
  };

  const FINAL = {
    util: 0.82,
    fatigue: 0.88,
    alpha: 3.8,
    freq: 1.82,
    sag: 0.88,
    sway: 0.88,
    settle: 0.96,
    ice: 0.96,
    oneSide: 0.92
  };

  function meets(r, T) {
    if (!r || r.error || r.ok !== true) return false;
    if (r.robustness === false) return false;

    if (typeof r.maxUtil === 'number' && r.maxUtil > T.util) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > T.fatigue) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < T.alpha) return false;
    if (typeof r.frequency === 'number' && r.frequency < T.freq) return false;

    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sagLimit > 0) {
      if (r.sag > T.sag * r.sagLimit) return false;
    }
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.swayLimit > 0) {
      if (r.sway > T.sway * r.swayLimit) return false;
    }

    if (r.cases) {
      for (const c of r.cases) {
        if (!c || typeof c.maxUtil !== 'number') continue;
        if (c.id === 'S' && c.maxUtil > T.settle) return false;
        if (c.id === 'I' && c.maxUtil > T.ice) return false;
        if (c.id === 'C2' && c.maxUtil > T.oneSide) return false;
      }
    }

    return true;
  }

  function bestMeeting(target) {
    let best = null;
    let bestMass = Infinity;
    for (const e of evals) {
      if (!e || !meets(e.r, target)) continue;
      const m = (e.r && typeof e.r.mass === 'number') ? e.r.mass : Infinity;
      if (m < bestMass) {
        bestMass = m;
        best = e;
      }
    }
    return best;
  }

  function reduce(startAssign, target) {
    let current = clone(startAssign);
    let currentEntry = evaluate(current);
    if (!currentEntry || !meets(currentEntry.r, target)) return null;

    for (let pass = 0; pass < 4 && calls < MAXCALLS - 10; pass++) {
      let changed = false;

      for (const g of groups) {
        if (calls >= MAXCALLS - 6) break;

        const curSpec = current[g];
        const curIdx = SEC.indexOf(curSpec);
        if (curIdx <= 0) continue;

        let lo = 0;
        let hi = curIdx - 1;
        let bestIdx = curIdx;
        let bestEntry = currentEntry;

        while (lo <= hi && calls < MAXCALLS - 4) {
          const mid = Math.floor((lo + hi) / 2);
          const trial = clone(current);
          trial[g] = SEC[mid];
          const e = evaluate(trial);
          if (!e) {
            hi = mid - 1;
            continue;
          }

          if (meets(e.r, target)) {
            bestIdx = mid;
            bestEntry = e;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (bestIdx < curIdx && bestEntry) {
          current[g] = SEC[bestIdx];
          currentEntry = bestEntry;
          changed = true;
        }
      }

      if (!changed) break;
    }

    return bestMeeting(target) || (meets(currentEntry.r, target) ? currentEntry : null);
  }

  const heavyAssign = {};
  for (const g of groups) heavyAssign[g] = SEC[SEC.length - 1];

  const heavy = evaluate(heavyAssign);

  let finalEntry = null;

  if (heavy && meets(heavy.r, SAFE)) {
    finalEntry = reduce(heavyAssign, SAFE);
  }

  if (!finalEntry) {
    const h2 = evaluate(heavyAssign);
    if (h2 && meets(h2.r, MOD)) {
      finalEntry = reduce(heavyAssign, MOD);
    }
  }

  if (!finalEntry) {
    const h3 = evaluate(heavyAssign);
    if (h3 && meets(h3.r, FINAL)) {
      finalEntry = reduce(heavyAssign, FINAL);
    }
  }

  if (!finalEntry) {
    finalEntry = bestMeeting(MOD) || bestMeeting(FINAL);
  }

  // Fallback: the known passing attempt-5 design, used only if the new
  // triangular topology cannot produce a checked design.
  function attempt5Design() {
    const XN = 19;
    const xb = 43.5 / 18;
    const xs = [];
    for (let i = 0; i < XN; i++) xs.push(i * xb);

    const yB = -4.0;
    const yT = 5.5;

    function did(side, j) {
      return (j % 2 === 0) ? (side + (j / 2)) : ('D' + side + j);
    }

    const nodes = [];
    for (let j = 0; j < XN; j++) {
      nodes.push({ id: 'BL' + j, x: xs[j], y: yB, z: -2.9 });
      nodes.push({ id: 'BR' + j, x: xs[j], y: yB, z:  2.9 });
      nodes.push({ id: 'TL' + j, x: xs[j], y: yT, z: -2.9 });
      nodes.push({ id: 'TR' + j, x: xs[j], y: yT, z:  2.9 });
      if (j % 2 === 1) {
        nodes.push({ id: 'DL' + j, x: xs[j], y: 0, z: -2.9 });
        nodes.push({ id: 'DR' + j, x: xs[j], y: 0, z:  2.9 });
      }
    }

    const M = {
      bottomChord: 'S460 CHS193.7x6.3',
      deckChord: 'S460 CHS457x16',
      topChord: 'S460 CHS323.9x10',
      vertLower: 'S460 CHS88.9x4',
      vertUpper: 'S460 CHS193.7x8',
      sideDiagLower: 'S460 CHS168.3x5',
      sideDiagUpper: 'S460 CHS219.1x8',
      transBeamBottom: 'S460 CHS88.9x4',
      transBeamDeck: 'S460 CHS355.6x12.5',
      transBeamTop: 'S460 CHS114.3x5',
      horizBraceBottom: 'S460 CHS139.7x6.3',
      horizBraceDeck: 'S460 CHS355.6x12.5',
      horizBraceTop: 'S460 CHS193.7x6.3',
      lowerCrossBrace: 'S460 CHS114.3x5',
      upperEndCross: 'S460 CHS193.7x6.3'
    };

    const members = [];
    const add = (a, b, g) => members.push([a, b, M[g]]);

    for (let j = 0; j < XN - 1; j++) {
      for (const side of ['L', 'R']) {
        add('B' + side + j, 'B' + side + (j + 1), 'bottomChord');
        add(did(side, j), did(side, j + 1), 'deckChord');
        add('T' + side + j, 'T' + side + (j + 1), 'topChord');
      }
    }

    for (let j = 0; j < XN; j++) {
      for (const side of ['L', 'R']) {
        add('B' + side + j, did(side, j), 'vertLower');
        add(did(side, j), 'T' + side + j, 'vertUpper');
      }
    }

    for (let j = 0; j < XN - 1; j++) {
      for (const side of ['L', 'R']) {
        if (j % 2 === 0) {
          add(did(side, j), 'B' + side + (j + 1), 'sideDiagLower');
          add('T' + side + j, did(side, j + 1), 'sideDiagUpper');
        } else {
          add('B' + side + j, did(side, j + 1), 'sideDiagLower');
          add(did(side, j), 'T' + side + (j + 1), 'sideDiagUpper');
        }
      }
    }

    for (let j = 0; j < XN; j++) {
      add('BL' + j, 'BR' + j, 'transBeamBottom');
      add(did('L', j), did('R', j), 'transBeamDeck');
      add('TL' + j, 'TR' + j, 'transBeamTop');
    }

    for (let j = 0; j < XN - 1; j++) {
      if (j % 2 === 0) add('BL' + j, 'BR' + (j + 1), 'horizBraceBottom');
      else add('BR' + j, 'BL' + (j + 1), 'horizBraceBottom');

      if ((j + 1) % 2 === 0) add(did('L', j), did('R', j + 1), 'horizBraceDeck');
      else add(did('R', j), did('L', j + 1), 'horizBraceDeck');

      if (j % 2 === 0) add('TL' + j, 'TR' + (j + 1), 'horizBraceTop');
      else add('TR' + j, 'TL' + (j + 1), 'horizBraceTop');
    }

    for (let j = 0; j < XN; j++) {
      if (j % 2 === 0) add('BL' + j, did('R', j), 'lowerCrossBrace');
      else add('BR' + j, did('L', j), 'lowerCrossBrace');
    }

    add('BR0', did('L', 0), 'lowerCrossBrace');
    add('BR' + (XN - 1), did('L', XN - 1), 'lowerCrossBrace');

    for (const j of [0, XN - 1]) {
      add(did('L', j), 'TR' + j, 'upperEndCross');
      add(did('R', j), 'TL' + j, 'upperEndCross');
    }

    return {
      note: 'Known-passing three-level through/under-deck fallback truss; S460 CHS',
      nodes,
      members
    };
  }

  if (!finalEntry || !finalEntry.r || finalEntry.r.ok !== true ||
      (typeof finalEntry.r.mass === 'number' && finalEntry.r.mass > 90000)) {
    return attempt5Design();
  }

  const out = buildTri(finalEntry.assign);
  const m = finalEntry.r && typeof finalEntry.r.mass === 'number'
    ? Math.round(finalEntry.r.mass)
    : '?';

  out.note = 'Triangular under-deck space truss: deck lines carry compression, a single lower central chord carries tension, all at y<=0; S460 CHS; nominal mass ' + m + ' kg';
  return out;
}

function design(site, analyse) {
  const SEC = [
    'S460 CHS33.7x2.6',
    'S460 CHS42.4x3.2',
    'S460 CHS48.3x3.2',
    'S460 CHS60.3x3.2',
    'S460 CHS60.3x4',
    'S460 CHS76.1x3.2',
    'S460 CHS76.1x4',
    'S460 CHS88.9x4',
    'S460 CHS88.9x5',
    'S460 CHS114.3x4',
    'S460 CHS114.3x5',
    'S460 CHS139.7x5',
    'S460 CHS139.7x6.3',
    'S460 CHS168.3x5',
    'S460 CHS168.3x6.3',
    'S460 CHS193.7x6.3',
    'S460 CHS193.7x8',
    'S460 CHS219.1x8',
    'S460 CHS244.5x8',
    'S460 CHS273x10',
    'S460 CHS323.9x10',
    'S460 CHS355.6x12.5',
    'S460 CHS406.4x12.5',
    'S460 CHS457x16'
  ];

  const GROUPS = [
    'b0','b1','b2','b3','b4',
    't0','t1','t2','t3','t4',
    'v0','v1','v2','v3',
    'sd0','sd1','sd2','sd3',
    'dt','tt','dd','td'
  ];

  const T0 = {
    util: 0.62,
    fat: 0.65,
    alpha: 6.5,
    freq: 2.00,
    sag: 0.60,
    sway: 0.60
  };

  const MAX_CALLS = 360;
  let calls = 0;
  const cache = new Map();
  const evals = [];

  function clone(a) {
    const b = {};
    for (let i = 0; i < GROUPS.length; i++) {
      const g = GROUPS[i];
      b[g] = a[g];
    }
    return b;
  }

  function allAssign(spec) {
    const a = {};
    for (let i = 0; i < GROUPS.length; i++) a[GROUPS[i]] = spec;
    return a;
  }

  function buildBow(assign, H) {
    const xs = [];
    for (let i = 0; i < 10; i++) xs.push(43.5 * i / 9);
    const y = new Array(10).fill(0);
    for (let i = 1; i <= 8; i++) {
      const f = i / 9;
      y[i] = Math.max(4.7, H * 4 * f * (1 - f));
    }

    const nodes = [];
    const members = [];
    for (let i = 1; i <= 8; i++) {
      nodes.push({ id: 'AL' + i, x: xs[i], y: y[i], z: -2.9 });
      nodes.push({ id: 'AR' + i, x: xs[i], y: y[i], z: 2.9 });
    }

    function add(a, b, g) {
      members.push([a, b, assign[g]]);
    }

    // Bottom chord / deck ties
    for (let i = 0; i < 9; i++) {
      const z = Math.min(i, 8 - i);
      const g = 'b' + z;
      add('L' + i, 'L' + (i + 1), g);
      add('R' + i, 'R' + (i + 1), g);
    }

    // Top arch chord
    for (let i = 0; i < 9; i++) {
      const z = Math.min(i, 8 - i);
      const g = 't' + z;
      let aL, bL, aR, bR;
      if (i === 0) {
        aL = 'L0'; bL = 'AL1';
        aR = 'R0'; bR = 'AR1';
      } else if (i === 8) {
        aL = 'AL8'; bL = 'L9';
        aR = 'AR8'; bR = 'R9';
      } else {
        aL = 'AL' + i; bL = 'AL' + (i + 1);
        aR = 'AR' + i; bR = 'AR' + (i + 1);
      }
      add(aL, bL, g);
      add(aR, bR, g);
    }

    // Vertical hangers / posts
    for (let i = 1; i <= 8; i++) {
      const z = Math.min(i, 9 - i) - 1;
      const g = 'v' + z;
      add('AL' + i, 'L' + i, g);
      add('AR' + i, 'R' + i, g);
    }

    // Side diagonals in interior panels 1..7
    for (let i = 1; i <= 7; i++) {
      const z = Math.min(i, 8 - i) - 1;
      const g = 'sd' + z;
      if (i % 2 === 1) {
        add('AL' + i, 'L' + (i + 1), g);
        add('AR' + i, 'R' + (i + 1), g);
      } else {
        add('AL' + (i + 1), 'L' + i, g);
        add('AR' + (i + 1), 'R' + i, g);
      }
    }

    // Deck transverse members
    for (let i = 0; i <= 9; i++) add('L' + i, 'R' + i, 'dt');

    // Top transverse members
    for (let i = 1; i <= 8; i++) add('AL' + i, 'AR' + i, 'tt');

    // Deck-plan diagonals
    for (let i = 0; i <= 8; i++) {
      if (i % 2 === 0) add('L' + i, 'R' + (i + 1), 'dd');
      else add('R' + i, 'L' + (i + 1), 'dd');
    }

    // Top-plan diagonals (only above the traffic envelope)
    for (let i = 1; i <= 7; i++) {
      if (i % 2 === 1) add('AL' + i, 'AR' + (i + 1), 'td');
      else add('AR' + i, 'AL' + (i + 1), 'td');
    }

    return {
      note: 'Two-plane bowstring/through truss above deck with triangulated side frames, deck-plane bracing and high-level cross-bracing; S460 CHS',
      nodes,
      members
    };
  }

  function meets(r, T) {
    if (!r || r.error || r.ok !== true) return false;
    if (r.robustness === false) return false;

    if (typeof r.maxUtil === 'number' && r.maxUtil > T.util) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > T.fat) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < T.alpha) return false;
    if (typeof r.frequency === 'number' && r.frequency < T.freq) return false;

    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sagLimit > 0) {
      if (r.sag > T.sag * r.sagLimit) return false;
    }
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.swayLimit > 0) {
      if (r.sway > T.sway * r.swayLimit) return false;
    }

    if (r.cases) {
      for (let i = 0; i < r.cases.length; i++) {
        const c = r.cases[i];
        if (!c) continue;
        if (typeof c.maxUtil === 'number' && c.maxUtil > T.util) return false;
      }
    }

    return true;
  }

  function evaluate(assign, H) {
    const key = H + '|' + GROUPS.map(g => assign[g]).join('|');
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX_CALLS) return null;

    let r;
    try {
      r = analyse(buildBow(assign, H));
    } catch (e) {
      r = { error: String(e), ok: false, mass: 1e12 };
    }

    calls++;
    const entry = { assign: clone(assign), r: r, H: H };
    cache.set(key, entry);
    evals.push(entry);
    return entry;
  }

  function bestMeeting(H, T) {
    let best = null;
    let bestMass = Infinity;
    for (let i = 0; i < evals.length; i++) {
      const e = evals[i];
      if (!e || e.H !== H) continue;
      if (!meets(e.r, T)) continue;
      const m = (e.r && typeof e.r.mass === 'number') ? e.r.mass : Infinity;
      if (m < bestMass) {
        bestMass = m;
        best = e;
      }
    }
    return best;
  }

  function optimize(H, target, startAssign, maxPasses) {
    let cur = clone(startAssign);
    let curE = evaluate(cur, H);
    if (!curE || !meets(curE.r, target)) return null;

    for (let pass = 0; pass < maxPasses && calls < MAX_CALLS - 6; pass++) {
      let changed = false;
      const order = (pass % 2 === 0) ? GROUPS.slice() : GROUPS.slice().reverse();

      for (let oi = 0; oi < order.length && calls < MAX_CALLS - 4; oi++) {
        const g = order[oi];
        const curSpec = cur[g];
        const curIdx = SEC.indexOf(curSpec);
        if (curIdx <= 0) continue;

        let lo = 0;
        let hi = curIdx - 1;
        let bestIdx = curIdx;
        let bestEntry = curE;

        while (lo <= hi && calls < MAX_CALLS - 2) {
          const mid = Math.floor((lo + hi) / 2);
          const trial = clone(cur);
          trial[g] = SEC[mid];
          const e = evaluate(trial, H);
          if (!e) {
            hi = mid - 1;
            continue;
          }

          if (meets(e.r, target)) {
            bestIdx = mid;
            bestEntry = e;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (bestIdx < curIdx && bestEntry) {
          cur = clone(bestEntry.assign);
          curE = bestEntry;
          changed = true;
        }
      }

      if (!changed) break;
    }

    return bestMeeting(H, target);
  }

  // Fallback: attempt-6 known-passing triangular under-deck space truss.
  function buildUnder6() {
    const XS = [];
    for (let i = 0; i < 10; i++) XS.push(43.5 * i / 9);
    const YB = -4.30;

    const nodes = [];
    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'C' + i, x: XS[i], y: YB, z: 0 });
    }

    const members = [];
    const add = (a, b, s) => members.push([a, b, s]);

    const M = {
      topChord: 'S460 CHS406.4x12.5',
      bottomChord: 'S460 CHS457x16',
      vBrace: 'S460 CHS273x10',
      sideDiag: 'S460 CHS323.9x10',
      deckDiag: 'S460 CHS323.9x10',
      deckTrans: 'S460 CHS273x10'
    };

    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1), M.topChord);
      add('R' + i, 'R' + (i + 1), M.topChord);
      add('C' + i, 'C' + (i + 1), M.bottomChord);
    }

    for (let i = 0; i < 10; i++) {
      add('L' + i, 'R' + i, M.deckTrans);
      add('L' + i, 'C' + i, M.vBrace);
      add('R' + i, 'C' + i, M.vBrace);
    }

    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) {
        add('L' + i, 'C' + (i + 1), M.sideDiag);
        add('R' + i, 'C' + (i + 1), M.sideDiag);
        add('L' + i, 'R' + (i + 1), M.deckDiag);
      } else {
        add('C' + i, 'L' + (i + 1), M.sideDiag);
        add('C' + i, 'R' + (i + 1), M.sideDiag);
        add('R' + i, 'L' + (i + 1), M.deckDiag);
      }
    }

    return {
      note: 'Fallback: known-passing triangular under-deck space truss; S460 CHS',
      nodes,
      members
    };
  }

  let bestT0 = null;

  const Hlist = [10.0, 9.4];

  for (let hi = 0; hi < Hlist.length && calls < MAX_CALLS - 20; hi++) {
    const H = Hlist[hi];
    let startEntry = null;

    // Find a generously sized start that already meets the strict target.
    const startIndices = [20, 21, 22, 23, 18, 19];
    for (let si = 0; si < startIndices.length; si++) {
      const idx = startIndices[si];
      if (idx < 0 || idx >= SEC.length) continue;
      if (calls >= MAX_CALLS - 8) break;

      const start = allAssign(SEC[idx]);
      const e = evaluate(start, H);
      if (!e) break;
      if (e.r && e.r.ok === true && meets(e.r, T0)) {
        startEntry = e;
        break;
      }
    }

    if (!startEntry) continue;

    const passes = (hi === 0 ? 2 : 1);
    const res = optimize(H, T0, startEntry.assign, passes);

    if (res && meets(res.r, T0)) {
      const m = (typeof res.r.mass === 'number') ? res.r.mass : Infinity;
      const bm = (bestT0 && typeof bestT0.r.mass === 'number') ? bestT0.r.mass : Infinity;
      if (!bestT0 || m < bm) {
        bestT0 = res;
      }
    }
  }

  if (bestT0) {
    const out = buildBow(bestT0.assign, bestT0.H);
    const mm = (bestT0.r && typeof bestT0.r.mass === 'number')
      ? Math.round(bestT0.r.mass)
      : '?';
    out.note = 'Light bowstring/through truss above deck, fully triangulated in side and plan planes, optimized with strict nominal margins; S460 CHS; nominal mass ' + mm + ' kg';
    return out;
  }

  return buildUnder6();
}

function design(site, analyse) {
  const GEO = [
    'CHS33.7x2.6','CHS42.4x3.2','CHS48.3x3.2','CHS60.3x3.2','CHS60.3x4',
    'CHS76.1x3.2','CHS76.1x4','CHS88.9x4','CHS88.9x5','CHS114.3x4',
    'CHS114.3x5','CHS139.7x5','CHS139.7x6.3','CHS168.3x5','CHS168.3x6.3',
    'CHS193.7x6.3','CHS193.7x8','CHS219.1x8','CHS244.5x8','CHS273x10',
    'CHS323.9x10','CHS355.6x12.5','CHS406.4x12.5','CHS457x16'
  ];

  const GROUPS = [
    'topC0','topC1','topC2',
    'botC0','botC1','botC2',
    'vertEnd','vert',
    'diagEnd','diagMid',
    'deckTrans','topTrans',
    'deckDiag','topDiag','endCross'
  ];

  const MAXCALLS = 390;
  let calls = 0;
  const cache = new Map();

  function cloneA(a) {
    const b = {};
    for (const g of GROUPS) b[g] = { gi: a[g].gi, mat: a[g].mat };
    return b;
  }

  function heavyAssign() {
    const a = {};
    for (const g of GROUPS) a[g] = { gi: GEO.length - 1, mat: 'S460' };
    return a;
  }

  function chordGroup(base, i) {
    const d = Math.min(i, 8 - i);
    return base + (d === 0 ? 0 : (d === 1 ? 1 : 2));
  }

  function buildOver(Y, assign) {
    const nodes = [];
    const members = [];
    const XS = [];
    for (let i = 0; i < 10; i++) XS.push(43.5 * i / 9);

    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'TL' + i, x: XS[i], y: Y, z: -2.9 });
      nodes.push({ id: 'TR' + i, x: XS[i], y: Y, z: 2.9 });
    }

    function add(a, b, g) {
      members.push([a, b, 'S460 ' + GEO[assign[g].gi]]);
    }

    for (let i = 0; i < 9; i++) {
      const gt = chordGroup('topC', i);
      const gb = chordGroup('botC', i);
      add('TL' + i, 'TL' + (i + 1), gt);
      add('TR' + i, 'TR' + (i + 1), gt);
      add('L' + i, 'L' + (i + 1), gb);
      add('R' + i, 'R' + (i + 1), gb);
    }

    for (let i = 0; i < 10; i++) {
      const gv = (i === 0 || i === 9) ? 'vertEnd' : 'vert';
      add('L' + i, 'TL' + i, gv);
      add('R' + i, 'TR' + i, gv);
      add('L' + i, 'R' + i, 'deckTrans');
      add('TL' + i, 'TR' + i, 'topTrans');
    }

    for (let i = 0; i < 9; i++) {
      const gd = (i <= 1 || i >= 7) ? 'diagEnd' : 'diagMid';
      if (i % 2 === 0) {
        add('TL' + i, 'L' + (i + 1), gd);
        add('TR' + i, 'R' + (i + 1), gd);
      } else {
        add('L' + i, 'TL' + (i + 1), gd);
        add('R' + i, 'TR' + (i + 1), gd);
      }

      if (i % 2 === 0) {
        add('L' + i, 'R' + (i + 1), 'deckDiag');
        add('TL' + i, 'TR' + (i + 1), 'topDiag');
      } else {
        add('R' + i, 'L' + (i + 1), 'deckDiag');
        add('TR' + i, 'TL' + (i + 1), 'topDiag');
      }
    }

    add('TL0', 'R0', 'endCross');
    add('TR0', 'L0', 'endCross');
    add('TL9', 'R9', 'endCross');
    add('TR9', 'L9', 'endCross');

    return {
      note: 'Constant-depth through box truss above the traffic envelope, fully triangulated in all four faces; S460 CHS',
      nodes: nodes,
      members: members
    };
  }

  function evalA(Y, a) {
    let key = String(Y);
    for (const g of GROUPS) key += '|' + a[g].mat + a[g].gi;
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAXCALLS) return null;
    calls++;
    let r;
    try {
      r = analyse(buildOver(Y, a));
    } catch (e) {
      r = { error: String(e), ok: false, mass: 1e12 };
    }
    cache.set(key, r);
    return r;
  }

  const T = {
    util: 0.62,
    fat: 0.72,
    alpha: 5.5,
    freq: 1.95,
    sag: 0.70,
    sway: 0.68
  };

  function meets(r, t) {
    if (!r || r.error || r.ok !== true) return false;
    if (r.robustness === false) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > t.util) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > t.fat) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < t.alpha) return false;
    if (typeof r.frequency === 'number' && r.frequency < t.freq) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sagLimit > 0) {
      if (r.sag > t.sag * r.sagLimit) return false;
    }
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.swayLimit > 0) {
      if (r.sway > t.sway * r.swayLimit) return false;
    }
    return true;
  }

  function optimize(Y, start, target, maxPasses) {
    let cur = cloneA(start);
    let curR = evalA(Y, cur);
    if (!curR || !meets(curR, target)) return null;

    for (let pass = 0; pass < maxPasses; pass++) {
      let changed = false;

      for (const g of GROUPS) {
        if (calls >= MAXCALLS - 4) break;
        const curGi = cur[g].gi;
        if (curGi <= 0) continue;

        let lo = 0;
        let hi = curGi - 1;
        let best = null;

        while (lo <= hi && calls < MAXCALLS - 2) {
          const mid = (lo + hi) >> 1;
          const trial = cloneA(cur);
          trial[g] = { gi: mid, mat: 'S460' };
          const e = evalA(Y, trial);

          if (e && meets(e, target)) {
            best = { assign: trial, e: e };
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (best) {
          cur = cloneA(best.assign);
          curR = best.e;
          changed = true;
        }
      }

      if (!changed || calls >= MAXCALLS - 4) break;
    }

    return {
      Y: Y,
      assign: cur,
      e: curR,
      mass: curR && typeof curR.mass === 'number' ? curR.mass : Infinity
    };
  }

  function buildUnder() {
    const XS = [];
    for (let i = 0; i < 10; i++) XS.push(43.5 * i / 9);
    const YB = -4.30;

    const nodes = [];
    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'C' + i, x: XS[i], y: YB, z: 0 });
    }

    const members = [];
    const add = (a, b, s) => members.push([a, b, s]);

    const M = {
      topChord: 'S460 CHS406.4x12.5',
      bottomChord: 'S460 CHS457x16',
      vBrace: 'S460 CHS273x10',
      sideDiag: 'S460 CHS323.9x10',
      deckDiag: 'S460 CHS323.9x10',
      deckTrans: 'S460 CHS273x10'
    };

    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1), M.topChord);
      add('R' + i, 'R' + (i + 1), M.topChord);
      add('C' + i, 'C' + (i + 1), M.bottomChord);
    }

    for (let i = 0; i < 10; i++) {
      add('L' + i, 'R' + i, M.deckTrans);
      add('L' + i, 'C' + i, M.vBrace);
      add('R' + i, 'C' + i, M.vBrace);
    }

    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) {
        add('L' + i, 'C' + (i + 1), M.sideDiag);
        add('R' + i, 'C' + (i + 1), M.sideDiag);
        add('L' + i, 'R' + (i + 1), M.deckDiag);
      } else {
        add('C' + i, 'L' + (i + 1), M.sideDiag);
        add('C' + i, 'R' + (i + 1), M.sideDiag);
        add('R' + i, 'L' + (i + 1), M.deckDiag);
      }
    }

    return {
      note: 'Fallback known-passing triangular under-deck space truss; S460 CHS',
      nodes: nodes,
      members: members
    };
  }

  const Ys = [10.35, 8.60, 6.90];
  const candidates = [];

  for (const Y of Ys) {
    if (calls > MAXCALLS - 90) break;
    const h = heavyAssign();
    const e0 = evalA(Y, h);
    if (e0 && meets(e0, T)) {
      const res = optimize(Y, h, T, 1);
      if (res && res.e && meets(res.e, T)) candidates.push(res);
    }
  }

  candidates.sort((a, b) => a.mass - b.mass);
  let best = candidates.length ? candidates[0] : null;

  if (best) {
    const refined = optimize(best.Y, best.assign, T, 2);
    if (refined && refined.e && meets(refined.e, T) && refined.mass < best.mass) {
      best = refined;
    }
  }

  if (best && best.e && best.e.ok === true && best.mass < 49574) {
    const out = buildOver(best.Y, best.assign);
    out.note = 'Constant-depth through box truss optimized below the known passing mass; S460 CHS; nominal mass ' +
      Math.round(best.mass) + ' kg';
    return out;
  }

  return buildUnder();
}

function design(site, analyse) {
  // Two Warren side trusses in the planes z = ±2.9 (on the traffic box faces), depth 10.4 m above the deck,
  // K-bracing across the top, cross girders and bracing on the deck plane (y = 0, box bottom face).
  // All joints pinned. Section sizes are set by group iteration on analyse() feedback.
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const H = 10.4;
  const MAT = 'S355';
  const CHS = ['CHS33.7x2.6', 'CHS42.4x3.2', 'CHS48.3x3.2', 'CHS60.3x3.2', 'CHS60.3x4', 'CHS76.1x3.2',
    'CHS76.1x4', 'CHS88.9x4', 'CHS88.9x5', 'CHS114.3x4', 'CHS114.3x5', 'CHS139.7x5', 'CHS168.3x5',
    'CHS139.7x6.3', 'CHS168.3x6.3', 'CHS193.7x6.3', 'CHS193.7x8', 'CHS219.1x8', 'CHS244.5x8',
    'CHS273x10', 'CHS323.9x10', 'CHS355.6x12.5', 'CHS406.4x12.5', 'CHS457x16'];
  const NG = 8;
  const TOP = CHS.length - 1;

  // top nodes
  const nodes = [];
  for (let i = 0; i < 10; i++) {
    nodes.push({ id: 'TL' + i, x: xs[i], y: H, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'TR' + i, x: xs[i], y: H, z: 2.9, joint: 'pin' });
  }

  // members: a, b, g (group)
  // groups: 0 top chord, 1 deck/bottom chord, 2 vertical, 3 web diagonal,
  //         4 top strut, 5 top K-diagonal, 6 deck cross girder, 7 deck-plane diagonal
  const M = [];
  const add = (a, b, g) => { M.push({ a: a, b: b, g: g }); };
  for (const s of ['L', 'R']) {
    const t = s === 'L' ? 'TL' : 'TR';
    for (let i = 0; i < 10; i++) add(s + i, t + i, 2);
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1), 1);
      add(t + i, t + (i + 1), 0);
      if (i % 2 === 0) add(s + i, t + (i + 1), 3);
      else add(t + i, s + (i + 1), 3);
    }
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i, 4);
  for (let i = 0; i < 9; i++) {
    add('TL' + i, 'TR' + (i + 1), 5);
    add('TR' + i, 'TL' + (i + 1), 5);
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i, 6);
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1), 7);

  const build = (ix) => ({
    note: 'Two Warren through trusses (depth 10.4 m) in planes z=±2.9, K top bracing, deck-plane cross girders and bracing, all pinned; sections sized group-wise from analysis feedback.',
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map(m => ({ a: m.a, b: m.b, spec: MAT + ' ' + CHS[ix[m.g]] }))
  });

  let idx = [16, 16, 12, 12, 8, 8, 10, 8];
  const floor = [0, 0, 0, 0, 0, 0, 0, 0];
  let best = null, bestMass = Infinity;
  let fallback = null;
  let last = null;
  let calls = 0;
  const t0 = Date.now();

  while (calls < 380 && Date.now() - t0 < 70000) {
    const d = build(idx);
    last = d;
    let r;
    try { r = analyse(d); } catch (e) { break; }
    calls++;
    if (!r || r.error) break;

    const valid = r.ok === true;
    const gmax = new Array(NG).fill(0);
    const gseen = new Array(NG).fill(false);
    M.forEach((m, k) => {
      const mm = r.members ? r.members[k] : null;
      if (mm && typeof mm.util === 'number') {
        gmax[m.g] = Math.max(gmax[m.g], mm.util);
        gseen[m.g] = true;
      }
    });
    const memMax = Math.max(...gmax);

    const globalBad =
      (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.93 * r.sagLimit) ||
      (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.93 * r.swayLimit) ||
      (typeof r.fMin === 'number' && r.fMin < 1.85) ||
      (typeof r.alphaCr === 'number' && r.alphaCr < 3.3);

    const good = valid && !globalBad && (typeof r.maxUtil !== 'number' || r.maxUtil <= 0.9);
    if (good && typeof r.mass === 'number' && r.mass < bestMass) {
      bestMass = r.mass;
      best = d;
    }
    if (valid && !fallback) fallback = d;

    const nidx = idx.slice();
    let changed = false;
    if (globalBad || (!valid && memMax <= 0.88)) {
      // global or unexplained failure: strengthen everything one step
      for (let g = 0; g < NG; g++) {
        if (nidx[g] < TOP) {
          nidx[g] += 1;
          floor[g] = Math.max(floor[g], nidx[g]);
          changed = true;
        }
      }
    } else {
      for (let g = 0; g < NG; g++) {
        if (!gseen[g]) continue;
        if (gmax[g] > 0.88 && nidx[g] < TOP) {
          nidx[g] += 1;
          floor[g] = Math.max(floor[g], nidx[g]);
          changed = true;
        } else if (valid && gmax[g] < 0.6 && nidx[g] > floor[g]) {
          nidx[g] -= 1;
          changed = true;
        }
      }
    }
    if (!changed) break;
    idx = nidx;
  }

  const out = best || fallback || last;
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

