  add('L0', 'TR0', 8);
  add('R0', 'TL0', 8);
  add('L9', 'TR9', 8);
  add('R9', 'TL9', 8);

  const build = (ix) => ({
    note: 'Two Warren side trusses at z=±2.9 (depth 10.4 m), single-diagonal top K-bracing and deck bracing, plus end-face transverse diagonals to stop the box shear mode; sections descent-sized from a safe start.',
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map(m => ({ a: m.a, b: m.b, spec: MAT + ' ' + CHS[ix[m.g]] }))
  });

  const ok = (r) => {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.85) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fMin === 'number' && r.fMin < 1.9) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.3) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.9) return false;
    return true;
  };

  let calls = 0;
  const t0 = Date.now();
  let best = null, bestMass = Infinity, lastD = null;
  const evalIdx = (ix) => {
    const d = build(ix);
    calls++;
    lastD = d;
    let r;
    try { r = analyse(d); } catch (e) { return null; }
    if (ok(r) && typeof r.mass === 'number' && r.mass < bestMass) {
      bestMass = r.mass;
      best = d;
    }
    return r;
  };
  const timeOK = () => Date.now() - t0 < 75000 && calls < 390;

  let idx = new Array(NG).fill(19);
  let r = evalIdx(idx);
  while (!ok(r) && idx[0] < TOP && timeOK()) {
    for (let g = 0; g < NG; g++) if (idx[g] < TOP) idx[g]++;
    r = evalIdx(idx);
  }

  if (ok(r)) {
    let improved = true;
    let rounds = 0;
    while (improved && rounds < 3 && timeOK()) {
      improved = false;
      rounds++;
      for (let g = 0; g < NG && timeOK(); g++) {
        while (idx[g] > 0 && timeOK()) {
          const t = idx.slice();
          t[g] -= 1;
          const rr = evalIdx(t);
          if (ok(rr)) { idx = t; improved = true; }
          else break;
        }
      }
    }
  }

  const out = best || lastD;
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

function design(site, analyse) {
  // Two Warren side trusses at z = ±2.9 (depth 10.4 m), with a mid-level node on every zig-zag
  // diagonal so each diagonal is two ~5.7 m segments (shorter buckling lengths). Mid-level cross
  // girders and bracing (y = 5.2, above the traffic box) keep the mid nodes out of plane.
  // Every member is sized individually from analyse() member utilisation (S690 CHS only).
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const H = 10.4, YM = 5.2, HALF = 4.833 / 2;
  const MAT = 'S690';
  const SEC = ['CHS33.7x2.6', 'CHS42.4x3.2', 'CHS48.3x3.2', 'CHS60.3x3.2', 'CHS60.3x4', 'CHS76.1x3.2',
    'CHS76.1x4', 'CHS88.9x4', 'CHS88.9x5', 'CHS114.3x4', 'CHS114.3x5', 'CHS139.7x5', 'CHS168.3x5',
    'CHS139.7x6.3', 'CHS168.3x6.3', 'CHS193.7x6.3', 'CHS193.7x8', 'CHS219.1x8', 'CHS244.5x8',
    'CHS273x10', 'CHS323.9x10', 'CHS355.6x12.5', 'CHS406.4x12.5', 'CHS457x16'];   // sorted by area
  const TOP = SEC.length - 1;

  // new nodes
  const nodes = [];
  for (let i = 0; i < 10; i++) {
    nodes.push({ id: 'TL' + i, x: xs[i], y: H, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'TR' + i, x: xs[i], y: H, z: 2.9, joint: 'pin' });
  }
  for (let i = 0; i < 9; i++) {
    const mx = Math.round((xs[i] + HALF) * 1000) / 1000;
    nodes.push({ id: 'ML' + i, x: mx, y: YM, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'MR' + i, x: mx, y: YM, z: 2.9, joint: 'pin' });
  }

  // members: a, b, g (group, informative only)
  // 0 vertical, 1 bottom chord, 2 top chord, 3 zig-zag diagonal segment, 4 mid chord,
  // 5 top strut, 6 top K, 7 deck cross, 8 deck diagonal, 9 end transverse, 10 mid cross, 11 mid bracing
  const M = [];
  const add = (a, b, g) => { M.push({ a: a, b: b, g: g }); };
  for (const s of ['L', 'R']) {
    const t = s === 'L' ? 'TL' : 'TR';
    const m = s === 'L' ? 'ML' : 'MR';
    for (let i = 0; i < 10; i++) add(s + i, t + i, 0);
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1), 1);
      add(t + i, t + (i + 1), 2);
      if (i % 2 === 0) { add(s + i, m + i, 3); add(m + i, t + (i + 1), 3); }
      else { add(t + i, m + i, 3); add(m + i, s + (i + 1), 3); }
    }
    for (let i = 0; i < 8; i++) add(m + i, m + (i + 1), 4);
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i, 5);
  for (let i = 0; i < 9; i++) {
    if (i % 2 === 0) add('TL' + i, 'TR' + (i + 1), 6);
    else add('TR' + i, 'TL' + (i + 1), 6);
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i, 7);
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1), 8);
  add('L0', 'TR0', 9);
  add('R0', 'TL0', 9);
  add('L9', 'TR9', 9);
  add('R9', 'TL9', 9);
  for (let i = 0; i < 9; i++) add('ML' + i, 'MR' + i, 10);
  for (let i = 0; i < 8; i++) {
    if (i % 2 === 0) add('ML' + i, 'MR' + (i + 1), 11);
    else add('MR' + i, 'ML' + (i + 1), 11);
  }

  const NM = M.length;
  const build = (ix) => ({
    note: 'Two Warren trusses at z=±2.9 with mid-level nodes splitting every diagonal (short buckling lengths), mid-level cross girders and bracing above the traffic box, S690 CHS sized member by member from utilisation feedback.',
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map((m, k) => ({ a: m.a, b: m.b, spec: MAT + ' ' + SEC[ix[k]] }))
  });

  let idx = new Array(NM).fill(19);
  const floor = new Array(NM).fill(0);
  let best = null, bestMass = Infinity, last = null;
  const t0 = Date.now();

  const passes = (r) => {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.92) return false;
    return true;
  };

  for (let it = 0; it < 60 && Date.now() - t0 < 72000; it++) {
    const d = build(idx);
    last = d;
    let r;
    try { r = analyse(d); } catch (e) { break; }
    if (!r || r.error) break;

    if (passes(r) && typeof r.mass === 'number' && r.mass < bestMass) {
      bestMass = r.mass;
      best = d;
    }

    const mem = Array.isArray(r.members) ? r.members : [];
    const nidx = idx.slice();
    let changed = false;
    let anyHigh = false;
    for (let k = 0; k < NM; k++) {
      const u = (mem[k] && typeof mem[k].util === 'number') ? mem[k].util : 0.5;
      if (u > 0.8) {
        anyHigh = true;
        if (nidx[k] < TOP) {
          nidx[k]++;
          floor[k] = Math.max(floor[k], nidx[k]);
          changed = true;
        }
      } else if (u < 0.6 && nidx[k] > floor[k]) {
        nidx[k]--;
        changed = true;
      }
    }
    // global failure with no member overloaded: stiffen everything one step
    if (r.ok !== true && !anyHigh) {
      for (let k = 0; k < NM; k++) {
        if (nidx[k] < TOP) {
          nidx[k]++;
          floor[k] = Math.max(floor[k], nidx[k]);
          changed = true;
        }
      }
    }
    if (!changed) break;
    idx = nidx;
  }

  const out = best || last;
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

function design(site, analyse) {
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const H = 10.4;
  const SEC = ['CHS33.7x2.6', 'CHS42.4x3.2', 'CHS48.3x3.2', 'CHS60.3x3.2', 'CHS60.3x4',
    'CHS76.1x3.2', 'CHS76.1x4', 'CHS88.9x4', 'CHS88.9x5', 'CHS114.3x4', 'CHS114.3x5',
    'CHS139.7x5', 'CHS168.3x5', 'CHS139.7x6.3', 'CHS168.3x6.3', 'CHS193.7x6.3', 'CHS193.7x8',
    'CHS219.1x8', 'CHS244.5x8', 'CHS273x10', 'CHS323.9x10', 'CHS355.6x12.5', 'CHS406.4x12.5',
    'CHS457x16'];
  const TOP = SEC.length - 1;
  const NG = 25;
  // groups: 0-4 top chord (symmetric panel index), 5-9 bottom chord, 10-14 verticals,
  // 15-19 web diagonals, 20 top strut, 21 top K, 22 deck cross girder, 23 deck diagonal, 24 end-frame diagonal

  const nodes = [];
  for (let i = 0; i < 10; i++) {
    nodes.push({ id: 'TL' + i, x: xs[i], y: H, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'TR' + i, x: xs[i], y: H, z: 2.9, joint: 'pin' });
  }
  const M = [];
  const add = (a, b, g) => { M.push({ a: a, b: b, g: g }); };
  const sym = (i, n) => Math.min(i, n - 1 - i);
  for (const s of ['L', 'R']) {
    const t = s === 'L' ? 'TL' : 'TR';
    for (let i = 0; i < 10; i++) add(s + i, t + i, 10 + sym(i, 10));
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1), 5 + sym(i, 9));
      add(t + i, t + (i + 1), sym(i, 9));
      if (i % 2 === 0) add(s + i, t + (i + 1), 15 + sym(i, 9));
      else add(t + i, s + (i + 1), 15 + sym(i, 9));
    }
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i, 20);
  for (let i = 0; i < 9; i++) {
    if (i % 2 === 0) add('TL' + i, 'TR' + (i + 1), 21);
    else add('TR' + i, 'TL' + (i + 1), 21);
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i, 22);
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1), 23);
  add('L0', 'TR0', 24);
  add('R0', 'TL0', 24);
  add('L9', 'TR9', 24);
  add('R9', 'TL9', 24);

  const build = (ix, mat) => ({
    note: 'Proven two-Warren-truss topology of attempt 2 with every symmetric member group sized by binary search on analysis feedback (' + mat + ' CHS), keeping utilisation, deflection, frequency and buckling margins.',
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map(m => ({ a: m.a, b: m.b, spec: mat + ' ' + SEC[ix[m.g]] }))
  });

  const pass = (r) => {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.8) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fMin === 'number' && r.fMin < 1.85) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.3) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.9) return false;
    return true;
  };

  const T0 = Date.now();
  let calls = 0;
  const cache = new Map();
  let best = null, bestMass = Infinity;

  const evalCfg = (ix, mat) => {
    const key = mat + '|' + ix.join(',');
    if (cache.has(key)) return cache.get(key);
    calls++;
    const d = build(ix, mat);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    const p = pass(r);
    if (p && typeof r.mass === 'number' && r.mass < bestMass) {
      bestMass = r.mass;
      best = d;
    }
    const res = { p: p };
    cache.set(key, res);
    return res;
  };

  const search = (mat, limitMs) => {
    const ix = new Array(NG).fill(TOP);
    if (Date.now() - T0 > limitMs) return;
    if (!evalCfg(ix, mat).p) return;
    let changed = true, sweeps = 0;
    while (changed && sweeps < 4) {
      changed = false;
      sweeps++;
      for (let g = 0; g < NG; g++) {
        if (Date.now() - T0 > limitMs || calls > 380) return;
        let lo = 0, hi = ix[g];
        while (lo < hi) {
          if (Date.now() - T0 > limitMs || calls > 380) break;
          const mid = (lo + hi) >> 1;
          const t = ix.slice();
          t[g] = mid;
          if (evalCfg(t, mat).p) hi = mid; else lo = mid + 1;
        }
        if (hi !== ix[g]) { ix[g] = hi; changed = true; }
      }
    }
  };

  search('S690', 40000);
  search('S355', 62000);

  if (!best) best = build(new Array(NG).fill(TOP), 'S355');
  return { note: best.note, nodes: best.nodes, joints: best.joints, members: best.members };
}

function design(site, analyse) {
