    'CHS219.1x8', 'CHS244.5x8', 'CHS273x10', 'CHS323.9x10', 'CHS355.6x12.5', 'CHS406.4x12.5',
    'CHS457x16'];
  const AREA = [2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18, 13.86, 17.17, 21.16,
    25.65, 26.4, 32.06, 37.09, 46.67, 53.06, 59.44, 82.62, 98.61, 134.74, 154.68, 221.67];
  const TOP = SEC.length - 1;

  // nodes (deck nodes L0..L9, R0..R9 already exist)
  const nodes = [];
  for (let i = 0; i < 10; i++) {
    nodes.push({ id: 'TL' + i, x: xs[i], y: H, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'TR' + i, x: xs[i], y: H, z: 2.9, joint: 'pin' });
  }

  // members [a, b]
  const M = [];
  const add = (a, b) => { M.push([a, b]); };
  for (const s of ['L', 'R']) {
    const t = s === 'L' ? 'TL' : 'TR';
    for (let i = 0; i < 10; i++) add(s + i, t + i);                 // verticals
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1));                                      // bottom chord
      add(t + i, t + (i + 1));                                      // top chord
      if (i % 2 === 0) add(s + i, t + (i + 1));                     // Warren diagonals
      else add(t + i, s + (i + 1));
    }
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i);             // top struts
  for (let i = 0; i < 9; i++) {                                     // top K bracing
    if (i % 2 === 0) add('TL' + i, 'TR' + (i + 1));
    else add('TR' + i, 'TL' + (i + 1));
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i);               // deck cross girders
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1));          // deck diagonals
  add('L0', 'TR0'); add('R0', 'TL0'); add('L9', 'TR9'); add('R9', 'TL9'); // end-face diagonals

  const NM = M.length;
  const memIndex = new Map();
  M.forEach((m, k) => memIndex.set(m[0] + '-' + m[1], k));

  const build = (ix, note) => ({
    note: note,
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map((m, k) => ({ a: m[0], b: m[1], spec: MAT + ' ' + SEC[ix[k]] }))
  });

  const passes = (r) => !!r && !r.error && r.ok === true &&
    typeof r.maxUtil === 'number' && r.maxUtil <= MAXU;

  const NOTE = 'Attempt-4 Warren topology with every member sized individually from analysis utilisation (S355 CHS, target util 0.8), returning the lightest passing iterate.';
  const T0 = Date.now();
  let idx = new Array(NM).fill(20);
  let best = null, bestMass = Infinity, calls = 0;

  while (calls < 60 && Date.now() - T0 < 50000) {
    const d = build(idx, NOTE);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    calls++;
    if (!r || r.error) break;

    if (passes(r) && typeof r.mass === 'number' && r.mass < bestMass) {
      bestMass = r.mass;
      best = d;
    }

    const u = new Array(NM).fill(-1);
    const mem = Array.isArray(r.members) ? r.members : [];
    for (let i = 0; i < mem.length; i++) {
      const mm = mem[i];
      if (!mm || typeof mm.util !== 'number') continue;
      const k = (mm.id !== undefined && memIndex.has(mm.id)) ? memIndex.get(mm.id) : i;
      if (k >= 0 && k < NM) u[k] = mm.util;
    }

    let maxU = 0;
    const next = idx.slice();
    for (let k = 0; k < NM; k++) {
      const uk = u[k] < 0 ? 0.5 : u[k];
      maxU = Math.max(maxU, uk);
      const need = AREA[idx[k]] * uk / TARGET;
      let j = 0;
      while (j < TOP && AREA[j] < need) j++;
      const lo = Math.max(0, idx[k] - STEP), hi = Math.min(TOP, idx[k] + STEP);
      next[k] = Math.min(hi, Math.max(lo, j));
    }
    // global failure with no member overloaded: stiffen everything one step
    if (r.ok !== true && maxU <= MAXU) {
      for (let k = 0; k < NM; k++) next[k] = Math.min(TOP, Math.max(next[k], idx[k] + 1));
    }

    let same = true;
    for (let k = 0; k < NM; k++) if (next[k] !== idx[k]) { same = false; break; }
    if (same) break;
    idx = next;
  }

  if (!best) best = build(new Array(NM).fill(TOP), 'Fallback: attempt-4 uniform CHS457x16 S355 (known to pass).');
  return { note: best.note, nodes: best.nodes, joints: best.joints, members: best.members };
}

