    const t = s === 'L' ? 'TL' : 'TR';
    for (let i = 0; i < 10; i++) add(s + i, t + i);
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1));
      add(t + i, t + (i + 1));
      if (i % 2 === 0) add(s + i, t + (i + 1));
      else add(t + i, s + (i + 1));
    }
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i);
  for (let i = 0; i < 9; i++) {
    if (i % 2 === 0) add('TL' + i, 'TR' + (i + 1));
    else add('TR' + i, 'TL' + (i + 1));
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i);
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1));
  add('L0', 'TR0'); add('R0', 'TL0'); add('L9', 'TR9'); add('R9', 'TL9');

  const NM = M.length;
  const memIndex = new Map();
  M.forEach((m, k) => memIndex.set(m[0] + '-' + m[1], k));
  M.forEach((m, k) => { if (!memIndex.has(m[1] + '-' + m[0])) memIndex.set(m[1] + '-' + m[0], k); });

  const build = (mat, idx) => ({
    note: NOTE,
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map((m, k) => ({ a: m[0], b: m[1], spec: PRE[mat[k]] + LIST[mat[k]][idx[k]][0] }))
  });

  const passes = (r) => {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil !== 'number' || r.maxUtil > MAXU) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fMin === 'number' && r.fMin < 1.8) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.5) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.85) return false;
    return true;
  };

  const nearest = (m, req) => {
    const L = LIST[m];
    for (let j = 0; j < L.length; j++) if (L[j][1] >= req) return j;
    return -1;
  };

  // one sizing step from the analysis report
  const plan = (r, mat, idx) => {
    const info = new Array(NM).fill(null);
    const arr = Array.isArray(r.members) ? r.members : [];
    for (let i = 0; i < arr.length; i++) {
      const mm = arr[i];
      if (!mm) continue;
      let k = -1;
      if (mm.id !== undefined && memIndex.has(String(mm.id))) k = memIndex.get(String(mm.id));
      else if (arr.length === NM) k = i;
      if (k >= 0) info[k] = mm;
    }
    const nm = mat.slice(), ni = idx.slice();
    let changed = false;
    for (let k = 0; k < NM; k++) {
      const inf = info[k] || {};
      const u = typeof inf.util === 'number' ? inf.util : 0.5;
      const cur = mat[k];
      const A = LIST[cur][idx[k]][1];
      const N = Math.max(Math.abs(Number(inf.tension) || 0), Math.abs(Number(inf.compression) || 0));
      const isFat = String(inf.mode || '').indexOf('fatigue') >= 0;
      const R = u * A * DFAT[cur] / 10;   // traffic force range (kN), valid when fatigue governs
      const opt = {};
      for (const m of ['T', 'A']) {
        const req = isFat
          ? Math.max(R * 10 / DFAT[m], N * 10 / (CHI * CAP[m])) / TARGET
          : u * A * CAP[cur] / (TARGET * CAP[m]);
        const j = nearest(m, req);
        opt[m] = j >= 0 ? { j: j, mass: RHO[m] * LIST[m][j][1] } : null;
      }
      let bm = null;
      for (const m of ['T', 'A']) if (opt[m] && (bm === null || opt[m].mass < opt[bm].mass)) bm = m;
      let tm, tj;
      if (bm === null) {
        tm = cur; tj = LIST[cur].length - 1;
      } else {
        tm = bm;
        if (bm !== cur && opt[cur] && opt[cur].mass <= 1.15 * opt[bm].mass) tm = cur; // hysteresis
        tj = opt[tm] ? opt[tm].j : LIST[tm].length - 1;
        if (tm === cur && !isFat) tj = Math.max(idx[k] - 4, Math.min(idx[k] + 4, tj));
      }
      nm[k] = tm; ni[k] = tj;
      if (tm !== mat[k] || tj !== idx[k]) changed = true;
    }
    return { mat: nm, idx: ni, changed: changed };
  };

  // global stiffening when only a global check fails
  const bump = (st) => {
    for (let k = 0; k < NM; k++) {
      if (st.idx[k] < LIST[st.mat[k]].length - 1) st.idx[k]++;
      else if (st.mat[k] === 'T') { st.mat[k] = 'A'; st.idx[k] = LIST.A.length - 1; }
    }
    st.changed = true;
  };

  const T0 = Date.now();
  let mat = new Array(NM).fill('T');
  let idx = new Array(NM).fill(7);   // start from TIMBER240x630 everywhere (should pass)
  let best = null, bestMass = Infinity, calls = 0;
  const seen = new Set();
  seen.add(mat.join('') + '|' + idx.join(','));

  while (calls < 160 && Date.now() - T0 < 72000) {
    const d = build(mat, idx);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    calls++;
    if (!r || r.error) break;
    const ok = passes(r);
    if (ok && typeof r.mass === 'number' && r.mass < bestMass) { bestMass = r.mass; best = d; }
    const st = plan(r, mat, idx);
    if (!ok && typeof r.maxUtil === 'number' && r.maxUtil <= MAXU) bump(st);
    const key = st.mat.join('') + '|' + st.idx.join(',');
    if (seen.has(key)) break;
    seen.add(key);
    mat = st.mat; idx = st.idx;
  }

  if (!best) {
    // fallback: the attempt-5 steel design, known to pass
    best = {
      note: 'Fallback: attempt-5 Warren topology with S355 CHS323.9x10 everywhere (known to pass).',
      nodes: nodes.map(n => Object.assign({}, n)),
      joints: {},
      members: M.map(m => ({ a: m[0], b: m[1], spec: 'S355 CHS323.9x10' }))
    };
  }
  return { note: best.note, nodes: best.nodes, joints: best.joints, members: best.members };
}

function design(site, analyse) {
  // Attempt-5/6 Warren topology (two Warren side trusses at z = ±2.9, top K bracing, deck cross girders,
  // deck diagonals, end-face diagonals), S355 CHS everywhere. Each member is re-sized from the analysis
  // utilisation report (area scaled by util / target, nearest catalogue section, step-limited).
  // The lightest design that passes with a margin for the unit variability is kept. If none is found,
  // the attempt-5/6 uniform CHS323.9x10 design is returned.
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const H = 10.4, MAT = 'S355';
  const TGT0 = 0.68, MAXU = 0.74, STEP = 5, TLIM = 74000;
  const SEC = ['CHS33.7x2.6', 'CHS42.4x3.2', 'CHS48.3x3.2', 'CHS60.3x3.2', 'CHS60.3x4',
    'CHS76.1x3.2', 'CHS76.1x4', 'CHS88.9x4', 'CHS88.9x5', 'CHS114.3x4', 'CHS114.3x5',
    'CHS139.7x5', 'CHS168.3x5', 'CHS139.7x6.3', 'CHS168.3x6.3', 'CHS193.7x6.3', 'CHS193.7x8',
    'CHS219.1x8', 'CHS244.5x8', 'CHS273x10', 'CHS323.9x10', 'CHS355.6x12.5', 'CHS406.4x12.5',
    'CHS457x16'];
  const AREA = [2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18, 13.86, 17.17, 21.16,
    25.65, 26.4, 32.06, 37.09, 46.67, 53.06, 59.44, 82.62, 98.61, 134.74, 154.68, 221.67];
  const TOP = SEC.length - 1;
  const FALLBACK_IDX = 20; // CHS323.9x10

  // nodes
  const nodes = [];
  for (let i = 0; i < 10; i++) {
    nodes.push({ id: 'TL' + i, x: xs[i], y: H, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'TR' + i, x: xs[i], y: H, z: 2.9, joint: 'pin' });
  }

  // members
  const M = [];
  const add = (a, b) => { M.push([a, b]); };
  for (const s of ['L', 'R']) {
    const t = s === 'L' ? 'TL' : 'TR';
    for (let i = 0; i < 10; i++) add(s + i, t + i);
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1));
      add(t + i, t + (i + 1));
      if (i % 2 === 0) add(s + i, t + (i + 1));
      else add(t + i, s + (i + 1));
    }
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i);
  for (let i = 0; i < 9; i++) {
    if (i % 2 === 0) add('TL' + i, 'TR' + (i + 1));
    else add('TR' + i, 'TL' + (i + 1));
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i);
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1));
  add('L0', 'TR0'); add('R0', 'TL0'); add('L9', 'TR9'); add('R9', 'TL9');

  const NM = M.length;
  const memIndex = new Map();
  M.forEach((m, k) => {
    memIndex.set(m[0] + '-' + m[1], k);
    if (!memIndex.has(m[1] + '-' + m[0])) memIndex.set(m[1] + '-' + m[0], k);
  });

  const build = (ix, note) => ({
    note: note,
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map((m, k) => ({ a: m[0], b: m[1], spec: MAT + ' ' + SEC[ix[k]] }))
  });

  const passes = (r) => {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil !== 'number' || r.maxUtil > MAXU) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fMin === 'number' && r.fMin < 1.8) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.5) return false;
    return true;
  };

  const getU = (r) => {
    const u = new Array(NM).fill(null);
    const arr = Array.isArray(r.members) ? r.members : [];
    for (let i = 0; i < arr.length; i++) {
      const mm = arr[i];
      if (!mm || typeof mm.util !== 'number') continue;
      let k = -1;
      if (mm.id !== undefined && memIndex.has(String(mm.id))) k = memIndex.get(String(mm.id));
      else if (arr.length === NM) k = i;
      if (k >= 0 && k < NM) u[k] = mm.util;
    }
    return u;
  };

  const NOTE = 'Attempt-5/6 Warren topology with every S355 CHS member re-sized from analysis utilisation (target 0.68, margin for unit scatter).';
  const T0 = Date.now();
  let idx = new Array(NM).fill(FALLBACK_IDX);
  let tgt = TGT0;
  let best = null, bestMass = Infinity, calls = 0, lastDt = 0;
  const seen = new Set();

  while (calls < 200) {
    const key = idx.join(',');
    if (seen.has(key)) break;
    if (Date.now() - T0 + 1.5 * lastDt > TLIM) break;
    seen.add(key);

    const d = build(idx, NOTE);
    const t1 = Date.now();
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    lastDt = Date.now() - t1;
    calls++;
    if (!r || r.error) break;

    const ok = passes(r);
    if (ok && typeof r.mass === 'number' && r.mass < bestMass) {
      bestMass = r.mass;
      best = d;
    }

    const u = getU(r);
    const maxU = typeof r.maxUtil === 'number' ? r.maxUtil : 1;
    if (!ok && maxU > MAXU && calls > 4) tgt = Math.max(0.55, tgt - 0.03);

    const next = new Array(NM);
    for (let k = 0; k < NM; k++) {
      const uk = u[k] === null ? 0.5 : u[k];
      const need = AREA[idx[k]] * uk / tgt;
      let j = 0;
      while (j < TOP && AREA[j] < need) j++;
      const lo = Math.max(0, idx[k] - STEP), hi = Math.min(TOP, idx[k] + STEP);
      next[k] = Math.min(hi, Math.max(lo, j));
    }
    // global failure with no member overloaded: stiffen everything one step
    if (r.ok !== true && maxU <= MAXU) {
      for (let k = 0; k < NM; k++) next[k] = Math.min(TOP, Math.max(next[k], idx[k] + 1));
    }
    idx = next;
  }

  if (!best) {
    best = build(new Array(NM).fill(FALLBACK_IDX),
      'Fallback: attempt-5/6 uniform S355 CHS323.9x10 Warren truss (known to pass).');
  }
  return { note: best.note, nodes: best.nodes, joints: best.joints, members: best.members };
}

function design(site, analyse) {
  // Warren side trusses at z = ±2.9 (attempt-7 topology, known to pass).
  // Members are re-sized each step from analysis feedback:
  //  - fatigue-governed members use the cheapest of S355 CHS or GL28 glulam that meets the traffic stress range
  //  - statically governed members scale their area with utilisation (target 0.72)
  // The lightest design passing a strict margin is returned; otherwise the lightest loose pass; otherwise the uniform fallback.
  const xs = [0, 4.833, 9.667, 14.5, 19.333, 24.167, 29, 33.833, 38.667, 43.5];
  const H = 10.4;
  const TGT = 0.72;
  const T0 = Date.now();
  const TLIM = 66000;
  const START = 'S355 CHS323.9x10';

  const CHS = [
    ['CHS33.7x2.6', 2.54], ['CHS42.4x3.2', 3.94], ['CHS48.3x3.2', 4.53], ['CHS60.3x3.2', 5.74],
    ['CHS60.3x4', 7.07], ['CHS76.1x3.2', 7.33], ['CHS76.1x4', 9.06], ['CHS88.9x4', 10.67],
    ['CHS88.9x5', 13.18], ['CHS114.3x4', 13.86], ['CHS114.3x5', 17.17], ['CHS139.7x5', 21.16],
    ['CHS168.3x5', 25.65], ['CHS139.7x6.3', 26.4], ['CHS168.3x6.3', 32.06], ['CHS193.7x6.3', 37.09],
    ['CHS193.7x8', 46.67], ['CHS219.1x8', 53.06], ['CHS244.5x8', 59.44], ['CHS273x10', 82.62],
    ['CHS323.9x10', 98.61], ['CHS355.6x12.5', 134.74], ['CHS406.4x12.5', 154.68], ['CHS457x16', 221.67]
  ];
  const TIM = [
    ['TIMBER90x180', 162], ['TIMBER115x225', 258.75], ['TIMBER140x270', 378], ['TIMBER160x315', 504],
    ['TIMBER190x360', 684], ['TIMBER190x450', 855], ['TIMBER215x540', 1161], ['TIMBER240x630', 1512],
    ['TIMBER280x720', 2016], ['TIMBER320x900', 2880]
  ];
  // A: cm2; Dst: static capacity per area (MPa, fy/gammaM, glulam after 20% outdoor loss);
  // Dfat: allowed traffic stress range (MPa) = Δσ(pinned) × (2e6/1e7)^(1/3)
  const POOL = [];
  for (const c of CHS) POOL.push({ spec: 'S355 ' + c[0], A: c[1], rho: 7850, Dst: 355 / 1.15, Dfat: 90 * 0.5848 });
  for (const t of TIM) POOL.push({ spec: 'GL28 ' + t[0], A: t[1], rho: 420, Dst: 22 * 0.8 / 1.15, Dfat: 8 * 0.5848 });
  for (const p of POOL) p.kg = p.rho * p.A * 1e-4;   // kg per m
  POOL.sort((a, b) => a.kg - b.kg);
  const startIdx = POOL.findIndex(p => p.spec === START);

  // nodes
  const nodes = [];
  for (let i = 0; i < 10; i++) {
    nodes.push({ id: 'TL' + i, x: xs[i], y: H, z: -2.9, joint: 'pin' });
    nodes.push({ id: 'TR' + i, x: xs[i], y: H, z: 2.9, joint: 'pin' });
  }
  // members
  const M = [];
  const add = (a, b) => { M.push([a, b]); };
  for (const s of ['L', 'R']) {
    const t = s === 'L' ? 'TL' : 'TR';
    for (let i = 0; i < 10; i++) add(s + i, t + i);
    for (let i = 0; i < 9; i++) {
      add(s + i, s + (i + 1));
      add(t + i, t + (i + 1));
      if (i % 2 === 0) add(s + i, t + (i + 1));
      else add(t + i, s + (i + 1));
    }
  }
  for (let i = 0; i < 10; i++) add('TL' + i, 'TR' + i);
  for (let i = 0; i < 9; i++) {
    if (i % 2 === 0) add('TL' + i, 'TR' + (i + 1));
    else add('TR' + i, 'TL' + (i + 1));
  }
  for (let i = 0; i < 10; i++) add('L' + i, 'R' + i);
  for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1));
  add('L0', 'TR0'); add('R0', 'TL0'); add('L9', 'TR9'); add('R9', 'TL9');

  const NM = M.length;
  const memIndex = new Map();
  M.forEach((m, k) => {
    memIndex.set(m[0] + '-' + m[1], k);
    if (!memIndex.has(m[1] + '-' + m[0])) memIndex.set(m[1] + '-' + m[0], k);
  });

  const build = (ix, note) => ({
    note: note,
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: M.map((m, k) => ({ a: m[0], b: m[1], spec: POOL[ix[k]].spec }))
  });

  // 2 = strict pass, 1 = loose pass, 0 = not acceptable
  const tierOf = (r) => {
    if (!r || r.error || r.ok !== true) return 0;
    if (typeof r.maxUtil !== 'number') return 0;
    const fr = typeof r.fMin === 'number' ? r.fMin : r.frequency;
    const fat = typeof r.fatigueWorst === 'number' ? r.fatigueWorst : 0;
    const ac = typeof r.alphaCr === 'number' ? r.alphaCr : 1e9;
    const within = (v, lim, f) => typeof v !== 'number' || typeof lim !== 'number' || v <= f * lim;
    const strict = r.maxUtil <= 0.80 && fat <= 0.80 && (typeof fr !== 'number' || fr >= 1.9) &&
      ac >= 4.0 && within(r.sag, r.sagLimit, 0.8) && within(r.sway, r.swayLimit, 0.8);
    if (strict) return 2;
    const loose = r.maxUtil <= 0.90 && fat <= 0.90 && (typeof fr !== 'number' || fr >= 1.75) &&
      ac >= 3.3 && within(r.sag, r.sagLimit, 0.95) && within(r.sway, r.swayLimit, 0.95);
    return loose ? 1 : 0;
  };

  const dN = new Array(NM).fill(0);   // remembered traffic stress-range force (kN) per member

  const nextState = (r, ix, boost) => {
    const info = new Array(NM).fill(null);
    const arr = Array.isArray(r.members) ? r.members : [];
    for (let i = 0; i < arr.length; i++) {
      const mm = arr[i];
      if (!mm) continue;
      let k = -1;
      if (mm.id !== undefined && memIndex.has(String(mm.id))) k = memIndex.get(String(mm.id));
      else if (arr.length === NM) k = i;
      if (k >= 0 && k < NM) info[k] = mm;
    }
    const nx = new Array(NM);
    for (let k = 0; k < NM; k++) {
      const mm = info[k] || {};
      const u = typeof mm.util === 'number' ? mm.util : 0.5;
      const p = POOL[ix[k]];
      const isFat = String(mm.mode || '').indexOf('fatigue') >= 0;
      const T = Math.abs(Number(mm.tension) || 0);
      const C = Math.abs(Number(mm.compression) || 0);
      const N = Math.max(T, C);
      const chi0 = C > T ? 0.6 : 1.0;
      if (isFat) dN[k] = u * p.A * p.Dfat / 10;   // kN: A(cm2) * D(MPa) / 10
      let pick = POOL.length - 1;
      for (let j = 0; j < POOL.length; j++) {
        const c = POOL[j];
        let need = isFat
          ? 10 * N / (TGT * c.Dst * chi0)
          : p.A * p.Dst * u / (TGT * c.Dst);
        if (dN[k] > 0) need = Math.max(need, 10 * dN[k] / (TGT * c.Dfat));
        need *= boost;
        if (c.A >= need) { pick = j; break; }
      }
      nx[k] = pick;
    }
    return nx;
  };

  let ix = new Array(NM).fill(startIdx);
  let boost = 1.0, best = null, bestMass = Infinity, bestTier = 0;
  let calls = 0, lastDt = 0;
  const seen = new Set();
  const NOTE = 'Warren side trusses with every member re-sized from analysis utilisation: GL28 glulam for fatigue-governed members, S355 CHS elsewhere (target util 0.72).';

  while (calls < 120) {
    const key = ix.join(',') + '|' + boost.toFixed(3);
    if (seen.has(key)) break;
    if (Date.now() - T0 + 1.3 * lastDt > TLIM) break;
    seen.add(key);

    const d = build(ix, NOTE);
    const t1 = Date.now();
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    lastDt = Date.now() - t1;
    calls++;
    if (!r || r.error) break;

    const tier = tierOf(r);
    if (tier > 0 && typeof r.mass === 'number') {
      if (tier > bestTier || (tier === bestTier && r.mass < bestMass)) {
        best = d; bestMass = r.mass; bestTier = tier;
      }
    }
    // global failure with no member overloaded: stiffen everything
    if (r.ok !== true && typeof r.maxUtil === 'number' && r.maxUtil <= 0.8) boost *= 1.1;
    ix = nextState(r, ix, boost);
  }

  if (!best) {
    best = build(new Array(NM).fill(startIdx),
      'Fallback: uniform S355 CHS323.9x10 Warren truss (known to pass).');
  }
  return { note: best.note, nodes: best.nodes, joints: best.joints, members: best.members };
}
